/* TourInsight browser application. All changing data is fetched from FastAPI/SQLite. */
const API = '/api';
const MONTHS = ['January','February','March','April','May','June','July','August','September','October','November','December'];
const INTERESTS = ['nature and hill stations','historical and heritage tourism','beaches','adventure and trekking','religious tourism','wildlife and forests','family sightseeing'];
const $ = (s,root=document)=>root.querySelector(s);
const $$ = (s,root=document)=>Array.from(root.querySelectorAll(s));
const state = {user:null,meta:null,communityMap:null,destinations:[],dashboard:null,lastPreferences:null,lastRecommendations:null,lastPlan:null,selectedCompare:new Set(),savedPlaces:new Set(JSON.parse(localStorage.getItem('tourinsight_saved_places')||'[]')),showSavedOnly:false,charts:{},destinationMap:null,planMap:null,adminTab:'imports',seasonalData:{},packingFilter:'all',packingItems:JSON.parse(localStorage.getItem('tourinsight_packing')||'null')};

function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function money(v){return '₹'+Number(v||0).toLocaleString('en-IN',{maximumFractionDigits:0});}
function nice(v){return String(v||'').replaceAll('_',' ').replace(/\b\w/g,x=>x.toUpperCase());}
function toast(message,type='success'){const el=document.createElement('div');el.className='toast '+(type==='error'?'error':'');el.textContent=message;$('#toast-region').append(el);setTimeout(()=>el.remove(),4200);}
function loading(on,message='Loading TourInsight…'){$('#loading-message').textContent=message;$('#global-loading').classList.toggle('hidden',!on);}
async function api(path,options={}){
  const opts={credentials:'same-origin',...options,headers:{...(options.headers||{})}};
  if(opts.body && !(opts.body instanceof FormData) && typeof opts.body!=='string'){opts.headers['Content-Type']='application/json';opts.body=JSON.stringify(opts.body);}
  const res=await fetch(API+path,opts);let data={};try{data=await res.json();}catch{}
  if(!res.ok){const msg=data.detail||data.message||`Request failed (${res.status})`;throw new Error(typeof msg==='string'?msg:JSON.stringify(msg));}
  return data;
}
function showPage(page){
  if(!$('#view-'+page)){page='overview';}
  $$('.view').forEach(v=>v.classList.toggle('active',v.id==='view-'+page));
  $$('.nav-item[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));
  const title={overview:'Home',explore:'Destination explorer',smartseason:'SmartSeason',planner:'Trip planner',toolkit:'Travel toolkit',community:'Travel community',fieldguide:'Stays & experiences',analytics:'Tourism analytics',sentiment:'Visitor experience',forecast:'Popularity forecast',pressure:'Pressure & opportunity',quality:'Data quality',admin:'Admin console'};
  $('#page-heading').textContent=title[page]||'Overview';
  $('#sidebar').classList.remove('open');window.location.hash=page;window.scrollTo({top:0,behavior:'smooth'});
  const loads={overview:loadOverview,explore:loadExplore,smartseason:loadSmartSeason,planner:loadPlanner,toolkit:loadToolkit,community:loadCommunity,fieldguide:()=>window.initFieldGuide?.(),analytics:loadAnalytics,sentiment:loadSentiment,forecast:loadForecast,pressure:loadPressure,quality:loadQuality,admin:loadAdmin};
  if(loads[page])loads[page]().catch(e=>toast(e.message,'error'));
}
function monthOptions(selected=new Date().getMonth()+1){return MONTHS.map((m,i)=>`<option value="${i+1}" ${i+1===Number(selected)?'selected':''}>${m}</option>`).join('');}
function daysOptions(sel=3){return Array.from({length:14},(_,i)=>i+1).map(d=>`<option value="${d}" ${d===Number(sel)?'selected':''}>${d} day${d>1?'s':''}</option>`).join('');}
function setMonthSelects(){
  $('#rec-month').innerHTML=monthOptions();
  $$('.month-select').forEach(el=>el.innerHTML=monthOptions());
  $('#rec-days').innerHTML=daysOptions(3);$$('.days-select').forEach(el=>el.innerHTML=daysOptions(3));
}
function setRegionSelects(){
  const options=(state.meta?.regions||['Any region']).map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('');
  $('#rec-region').innerHTML=options;$$('.region-select').forEach(x=>x.innerHTML=options);
  $('#dest-region').innerHTML=options;
  $('#dest-category').innerHTML='<option>All categories</option>'+(state.meta?.categories||[]).map(x=>`<option>${esc(x)}</option>`).join('');
}
function setInterestOptions(){
  const html=INTERESTS.map(x=>`<label class="interest-option"><input type="checkbox" value="${esc(x)}"><span>${esc(nice(x))}</span></label>`).join('');
  $('#interest-options').innerHTML=html;$('#planner-interests').innerHTML=html;
}
function formatKpi(label,value,foot,icon){return `<div class="kpi-card"><div class="kpi-top"><span>${esc(label)}</span><span class="kpi-icon">${icon}</span></div><div class="kpi-value">${esc(value)}</div><div class="kpi-foot">${esc(foot)}</div></div>`;}
function chart(id,config){if(!window.Chart)return;const el=document.getElementById(id);if(!el)return;if(state.charts[id])state.charts[id].destroy();state.charts[id]=new Chart(el,config);}
const chartDefaults={responsive:true,maintainAspectRatio:false,plugins:{legend:{labels:{color:'#81918b',font:{family:'DM Sans',size:9},boxWidth:9,boxHeight:9,usePointStyle:true}},tooltip:{backgroundColor:'#183d43',titleFont:{family:'DM Sans'},bodyFont:{family:'DM Sans'},padding:10}},scales:{x:{grid:{display:false},ticks:{color:'#8c9b95',font:{size:8,family:'DM Sans'}}},y:{grid:{color:'#edf1ee'},ticks:{color:'#8c9b95',font:{size:8,family:'DM Sans'}}}}};
function clone(obj){return JSON.parse(JSON.stringify(obj));}
function imageTag(url,name,cls=''){return `<img class="${cls}" src="${esc(url||'')}" alt="${esc(name)}" loading="lazy" onerror="this.onerror=null;this.src='https://images.unsplash.com/photo-1470770841072-f978cf4d019e?auto=format&fit=crop&w=900&q=75'">`;}

async function init(){
  setMonthSelects();setInterestOptions();
  if($('#checkin-form input[name=visited_on]'))$('#checkin-form input[name=visited_on]').value=new Date().toISOString().slice(0,10);
  const savedLang=localStorage.getItem('tourinsight_language')||'en';if($('#language-select'))$('#language-select').value=savedLang;applyLanguage(savedLang);
  try{state.meta=await api('/meta');setRegionSelects();}catch(e){toast('Could not load app metadata: '+e.message,'error');}
  await Promise.allSettled([refreshAuth(),refreshDestinations(),refreshHealth()]);
  // Respect a local password reset token in the URL.
  const params=new URLSearchParams(location.search);const reset=params.get('reset');
  if(reset){openResetModal(reset);}
  const hash=location.hash.replace('#','');if(hash&&$('#view-'+hash))showPage(hash);else await loadOverview();
}
async function refreshHealth(){try{const h=await api('/health');$('#api-status').textContent=`SQLite connected · ${h.active_destinations} destinations`;}catch{$('#api-status').textContent='API unavailable';}}
async function refreshAuth(){
  try{const data=await api('/auth/me');state.user=data.user;renderUser();}catch{state.user=null;renderUser();}
}
function renderUser(){
  const logged=!!state.user;$('#user-name').textContent=logged?state.user.full_name:'Guest session';$('#user-role').textContent=logged?(state.user.role==='admin'?'Administrator':'Tourist account'):'Explore as visitor';$('#user-avatar').textContent=logged?state.user.full_name.trim().charAt(0).toUpperCase():'G';
  $('#auth-button').textContent=logged?'⋯':'↗';$('#auth-button').title=logged?'Account options':'Sign in';$('#top-auth').classList.toggle('hidden',logged);$('#profile-button').classList.toggle('hidden',!logged);$('#admin-nav').classList.toggle('hidden',!logged||state.user.role!=='admin');
}
async function refreshDestinations(){const d=await api('/destinations');state.destinations=d.destinations;const opts=state.destinations.map(x=>`<option value="${esc(x.slug)}">${esc(x.name)}</option>`).join('');if($('#review-destination'))$('#review-destination').innerHTML=opts;['community-destination','journal-destination','checkin-destination','transport-destination'].forEach(id=>{const el=$('#'+id);if(el){const first=id==='community-destination'?'<option value="">General Karnataka travel</option>':id==='journal-destination'?'<option value="">Choose a destination</option>':'';el.innerHTML=first+opts;}});}

async function loadOverview(){
  const d=await api('/dashboard');state.dashboard=d;
  $('#overview-kpis').innerHTML=[formatKpi('Destinations in catalogue',d.kpis.destinations,'Karnataka reference destinations','⌖'),formatKpi('Tourism data records',d.kpis.tourism_records,'Imported monthly visitor records','▥'),formatKpi('Visitor reviews',d.kpis.review_count,'Stored visitor feedback','♡'),formatKpi('Average visitor rating',d.kpis.avg_rating??'—',d.kpis.avg_rating?'Calculated from submitted / imported reviews':'No review ratings available','★')].join('');
  const top=[...d.popularity_ranking].sort((a,b)=>b.popularity_index-a.popularity_index).slice(0,3);
  $('#overview-destinations').innerHTML=top.map((x,i)=>{const dest=state.destinations.find(y=>y.slug===x.slug);return `<div class="mini-destination" data-action="destination-detail" data-slug="${esc(x.slug)}">${imageTag(dest?.image_url,x.name)}<div class="mini-destination-copy"><b>${esc(x.name)}</b><small>${esc(x.category)} · Index ${Math.round(x.popularity_index||0)}</small></div></div>`;}).join('');
  const monthNames=MONTHS.map(x=>x.slice(0,3));chart('overview-season-chart',{type:'line',data:{labels:monthNames,datasets:[{label:'Average seasonal suitability',data:d.seasonality.map(x=>Number(x.score.toFixed(1))),borderColor:'#4f9b88',backgroundColor:'rgba(79,155,136,.12)',fill:true,tension:.35,pointRadius:2,pointBackgroundColor:'#4f9b88'}]},options:{...clone(chartDefaults),plugins:{...chartDefaults.plugins,legend:{display:false}},scales:{...chartDefaults.scales,y:{...chartDefaults.scales.y,min:0,max:100}}}});
}

function renderDestinationCard(d){
  const checked=state.selectedCompare.has(d.slug)?'checked':'';
  return `<article class="destination-card" data-action="destination-detail" data-slug="${esc(d.slug)}"><div class="destination-photo">${imageTag(d.image_url,d.name)}<span class="photo-tag">${esc(d.category)}</span><span class="photo-rating">${d.rating?`★ ${d.rating.average} (${d.rating.count})`:'No reviews yet'}</span><button type="button" class="favorite-button ${state.savedPlaces.has(d.slug)?'is-saved':''}" data-action="toggle-favorite" data-slug="${esc(d.slug)}" aria-label="${state.savedPlaces.has(d.slug)?'Remove':'Save'} ${esc(d.name)} ${state.savedPlaces.has(d.slug)?'from':'to'} saved places" title="Save place">${state.savedPlaces.has(d.slug)?'♥':'♡'}</button></div><div class="destination-card-body"><div class="destination-card-title"><div><h3>${esc(d.name)}</h3><small>${esc(d.district||'Karnataka')} · ${esc(d.region||'')}</small></div><span class="discoverability">Index ${Math.round(d.popularity_index||0)}</span></div><p class="destination-description">${esc(d.description)}</p><div class="card-tags">${(d.tags||[]).slice(0,3).map(t=>`<span class="tag tag-muted">${esc(nice(t))}</span>`).join('')}</div><div class="card-meta-row"><span>Indicative daily spend</span><b>${money(d.budget_low)} – ${money(d.budget_high)}</b></div><label class="compare-check" onclick="event.stopPropagation()"><input type="checkbox" data-compare="${esc(d.slug)}" ${checked}> Add to compare</label></div></article>`;
}
async function loadExplore(){await refreshDestinations();renderDestinationMap();renderDestinationGrid();}
function renderDestinationGrid(){
  const q=$('#dest-search').value.toLowerCase();const region=$('#dest-region').value;const category=$('#dest-category').value;const sort=$('#dest-sort').value;
  let ds=state.destinations.filter(d=>(!state.showSavedOnly||state.savedPlaces.has(d.slug))&&(!q||[d.name,d.district,d.description,d.region].join(' ').toLowerCase().includes(q))&&(region==='Any region'||d.region===region||d.district===region)&&(category==='All categories'||d.category===category));
  if(sort==='popularity')ds.sort((a,b)=>b.popularity_index-a.popularity_index);else if(sort==='budget')ds.sort((a,b)=>a.budget_low-b.budget_low);else if(sort==='accessibility')ds.sort((a,b)=>b.accessibility_score-a.accessibility_score);else ds.sort((a,b)=>a.name.localeCompare(b.name));
  $('#destination-grid').innerHTML=ds.length?ds.map(renderDestinationCard).join():'<div class="empty-state" style="grid-column:1/-1">No destinations match these filters. Try a different keyword or region.</div>';
  $('#destination-count').innerHTML=`${ds.length}<small>${state.showSavedOnly?'saved places':'destinations'}</small>`;$('#saved-count').textContent=state.savedPlaces.size;$('#saved-filter').classList.toggle('is-active',state.showSavedOnly);$('#saved-filter').setAttribute('aria-pressed',String(state.showSavedOnly));$('#compare-count').textContent=`${state.selectedCompare.size} selected · Choose up to 4 places to compare.`;$('#compare-selected').disabled=state.selectedCompare.size<2;
}
function renderDestinationMap(){
  if(!window.L)return;const el=$('#destination-map');if(!el)return;if(state.destinationMap){state.destinationMap.remove();state.destinationMap=null;}
  const map=L.map(el,{scrollWheelZoom:false}).setView([14.1,76.0],6);state.destinationMap=map;
  L.tileLayer('https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png',{attribution:'© OpenStreetMap contributors · © CARTO',subdomains:'abcd',maxZoom:19}).addTo(map);
  state.destinations.forEach(d=>{const marker=L.circleMarker([d.latitude,d.longitude],{radius:7,color:'#fff',weight:2,fillColor:'#448d7c',fillOpacity:1}).addTo(map);marker.bindPopup(`<div class="map-popup-title">${esc(d.name)}</div><a class="map-popup-link" href="#" data-map-slug="${esc(d.slug)}">Explore destination →</a>`);marker.on('popupopen',()=>{const a=document.querySelector(`[data-map-slug="${d.slug}"]`);if(a)a.onclick=(ev)=>{ev.preventDefault();openDestinationDetail(d.slug);};});});
  setTimeout(()=>map.invalidateSize(),120);
}
async function openDestinationDetail(slug){
  try{const data=await api('/destinations/'+encodeURIComponent(slug));const d=data.destination;const nearby=state.destinations.filter(x=>x.slug!==d.slug).map(x=>({...x,distance:Math.round(6371*2*Math.asin(Math.sqrt(Math.sin((x.latitude-d.latitude)*Math.PI/360)**2+Math.cos(d.latitude*Math.PI/180)*Math.cos(x.latitude*Math.PI/180)*Math.sin((x.longitude-d.longitude)*Math.PI/360)**2)))})).filter(x=>x.distance<220).sort((a,b)=>a.distance-b.distance).slice(0,3);const nearbyHtml=`<div class="nearby-strip"><h4>Nearby destinations to pair with this stop</h4><div>${nearby.map(x=>`<button class="nearby-place" data-action="destination-detail" data-slug="${esc(x.slug)}"><b>${esc(x.name)}</b><small>Approx. ${x.distance} km · ${esc(x.district||'Karnataka')}</small></button>`).join('')||'<span class="panel-subtext">No nearby destination in the current starter catalogue.</span>'}</div></div>`;showModal(`<div class="detail-hero">${imageTag(d.image_url,d.name)}<div><span class="eyebrow">${esc(d.category)} · ${esc(d.region||'Karnataka')}</span><h2>${esc(d.name)}</h2><p>${esc(d.description)}</p><div class="detail-chip-row"><span class="tag tag-muted">${esc(d.district)}</span><span class="tag tag-muted">${money(d.budget_low)}–${money(d.budget_high)} / person / day</span><span class="tag tag-muted">${d.visit_days} recommended day(s)</span></div><p><b>Season guidance:</b> ${esc(d.season_note||'Not available')}</p><div id="detail-weather" class="source-note">Loading live weather from Open-Meteo…</div></div></div><div class="detail-lists"><div><h4>Main attractions</h4><ul>${d.attractions.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div><div><h4>Travel interests</h4><ul>${d.interests.map(x=>`<li>${esc(nice(x))}</li>`).join('')}</ul><h4>Planning notes</h4><p class="panel-subtext">Accessibility index: ${d.accessibility_score}/100 · Editorial baseline</p><p class="panel-subtext">Popularity index: ${d.popularity_index}/100 · Not official visitor volume</p></div></div>${nearbyHtml}<div class="eyebrow" style="margin-top:16px">MONTHLY SEASONAL SUITABILITY</div><div class="detail-months">${data.seasonal.map(x=>`<div class="detail-month"><b>${MONTHS[x.month-1].slice(0,3)}</b><span>${Math.round(x.score)}</span></div>`).join('')}</div><p class="panel-subtext" style="margin-top:10px">Indicative editorial guidance for month selection, not observed climate data. Historical weather can be checked in SmartSeason when the Open-Meteo archive is reachable.</p><div class="detail-lists"><div><h4>Visitor review coverage</h4><p class="panel-subtext">${data.reviews.length?`${data.reviews.length} stored reviews.`:'No verified reviews or user feedback have been stored yet.'}</p></div><div><h4>Current weather</h4><p class="panel-subtext">Live weather is retrieved on demand; if the API is unavailable the application will show that status.</p></div></div>`,true);
    api('/weather/'+encodeURIComponent(slug)).then(w=>{const el=$('#detail-weather');if(!el)return;if(!w.available){el.textContent='Live weather unavailable: '+(w.error||w.message||'No current conditions returned.');return;}const c=w.current||{},daily=w.daily||{};const forecast=(daily.time||[]).slice(0,7).map((day,i)=>`${new Date(day+'T00:00:00').toLocaleDateString('en-IN',{day:'numeric',month:'short'})}: ${daily.temperature_2m_max?.[i]??'—'}°/${daily.temperature_2m_min?.[i]??'—'}° · rain ${daily.precipitation_sum?.[i]??'—'} mm`).join('<br>');el.innerHTML=`<b>LIVE WEATHER · OPEN-METEO</b><br>${esc(c.temperature_2m??'—')}°C · Feels ${esc(c.apparent_temperature??'—')}°C · Humidity ${esc(c.relative_humidity_2m??'—')}% · Wind ${esc(c.wind_speed_10m??'—')} km/h<br><small>Retrieved ${esc(w.retrieved_at||'now')} · ${esc(w.timezone||'')}</small><br><br><b>7-DAY FORECAST</b><br>${forecast}`;}).catch(()=>{const el=$('#detail-weather');if(el)el.textContent='Live weather service could not be reached.';});
  }catch(e){toast(e.message,'error');}
}

async function loadSmartSeason(){
  if(!state.meta)state.meta=await api('/meta');
  const d=await api('/weights').catch(()=>null);if(d)renderWeightList(d.weights);
}
function renderWeightList(weights){const list=$('#weight-list');if(!list)return;list.innerHTML=weights.map(w=>`<div class="weight-row"><span>${esc(w.label)}</span><b>${Number(w.value).toFixed(0)}%</b><i style="--w:${Number(w.value)}%"></i></div>`).join();}
function formPrefs(form){const fd=new FormData(form);return {origin:String(fd.get('origin')||'Bengaluru'),region:String(fd.get('region')||'Any region'),month:Number(fd.get('month')||new Date().getMonth()+1),interests:$$('input[type=checkbox]:checked',form).map(x=>x.value),budget:Number(fd.get('budget')||30000),days:Number(fd.get('days')||3),travellers:Number(fd.get('travellers')||1),group:String(fd.get('group')||'family')};}
function recommendationCard(d,index){
  const matched=d.interests.filter(x=>state.lastPreferences?.interests.includes(x));
  const reasons=d.reasons.slice(0,2).map(x=>`<span class="reason-chip">${esc(x)}</span>`).join('');
  const weather=d.weather?.available?`${d.weather.avg_max_c}° / ${d.weather.avg_min_c}°C historical average · ${d.weather.wet_days_pct}% wet days`:'Historical climate unavailable';
  const crowd=d.crowd?.label||'Crowd data unavailable';
  return `<article class="result-card"><img class="result-photo" src="${esc(d.image)}" alt="${esc(d.name)}" onerror="this.src='https://images.unsplash.com/photo-1470770841072-f978cf4d019e?auto=format&fit=crop&w=800&q=70'"><div class="result-main"><div class="result-title"><span class="eyebrow">MATCH ${String(index+1).padStart(2,'0')}</span><h3>${esc(d.name)}</h3><span class="tag tag-muted">${esc(d.category)}</span></div><p>${esc(d.description)}</p><div class="reason-list">${reasons}</div><div class="result-detail"><div class="result-detail-grid"><div><b>WEATHER FIT</b><span>${esc(weather)}</span></div><div><b>ESTIMATED SPEND / DAY</b><span>${money(d.budget_low)}–${money(d.budget_high)} per person</span></div><div><b>ACCESSIBILITY</b><span>${d.accessibility}/100 · editorial baseline</span></div><div><b>RECOMMENDED DURATION</b><span>${d.visit_days} day(s)</span></div><div><b>BEST VISITING CONDITIONS</b><span>${esc(d.season_label)} · ${esc(d.season_note||'Check local conditions before travel.')}</span></div><div><b>CROWD INDICATOR</b><span>${esc(crowd)}</span></div><div><b>ATTRACTIONS</b><span>${esc(d.attractions.join(', '))}</span></div><div><b>THINGS TO CONSIDER</b><span>${esc(d.disadvantages.join(' ')||'Confirm opening hours and local conditions before travelling.')}</span></div></div><div class="source-note" style="margin-top:10px">${esc(d.weather?.basis||'Weather coverage unavailable.')} Score uses ${d.score_coverage}% of configured weighted factors.</div></div></div><div class="result-actions"><div class="score-ring">${Math.round(d.score)}<small>/ 100</small></div><button class="text-link" data-action="toggle-result">View breakdown ↓</button><button class="text-link" data-action="destination-detail" data-slug="${esc(d.slug)}">Destination details ↗</button><button class="text-link" data-action="alternatives" data-slug="${esc(d.slug)}">Find alternatives ↗</button></div></article>`;
}
function renderRecommendations(data){
  state.lastRecommendations=data;const root=$('#recommend-results');root.classList.remove('hidden');
  root.innerHTML=`<div class="results-head"><div><span class="eyebrow">YOUR SMARTSEASON MATCHES</span><h2>Five places worth discovering.</h2><p>Ranked for ${MONTHS[data.month-1]} · ${esc(state.lastPreferences?.origin||'your origin')} · Score re-normalised to available data.</p></div><button class="button button-secondary button-small" data-page="planner">Plan a route ↗</button></div><div class="source-note"><b>Scoring transparency.</b> ${esc(data.method)} Popularity is a local editorial discoverability baseline, not official visitor volume. Weather is based on historical monthly climate, not a date-specific forecast.</div><div class="result-list">${data.results.map(recommendationCard).join('')}</div><div class="panel" style="margin-top:13px"><div class="panel-head"><div><span class="eyebrow">DATA NOTES</span><h3>What went into this ranking</h3></div></div><div class="quality-notes">${data.data_notes.map(x=>`<div class="quality-note"><span>✦</span>${esc(x)}</div>`).join('')}</div></div><div id="alternative-results"></div>`;
}
async function submitRecommendations(form){
  const payload=formPrefs(form);state.lastPreferences=payload;$('#recommend-submit').disabled=true;$('#recommend-submit').textContent='Calculating available signals…';
  try{const result=await api('/recommendations',{method:'POST',body:payload});renderRecommendations(result);toast('SmartSeason recommendations are ready.');$('#recommend-results').scrollIntoView({behavior:'smooth',block:'start'});}catch(e){toast(e.message,'error');}finally{$('#recommend-submit').disabled=false;$('#recommend-submit').innerHTML='Generate my top five <span>✧</span>';}
}
async function showAlternatives(slug){
  if(!state.lastPreferences){toast('Generate your SmartSeason recommendations first.','error');return;}
  const root=$('#alternative-results');root.innerHTML='<div class="empty-state">Finding similar destination alternatives…</div>';
  try{const data=await api('/alternatives',{method:'POST',body:{...state.lastPreferences,target_slug:slug}});root.innerHTML=`<div class="panel" style="margin-top:14px"><div class="panel-head"><div><span class="eyebrow">ALTERNATIVE DISCOVERY</span><h3>Other ways to make this trip work</h3><p class="panel-subtext">Alternatives to ${esc(data.target)} based on matching interest categories and your same SmartSeason preferences.</p></div></div><div class="destination-strip">${data.alternatives.map(d=>`<div class="mini-destination" data-action="destination-detail" data-slug="${esc(d.slug)}">${imageTag(d.image,d.name)}<div class="mini-destination-copy"><b>${esc(d.name)}</b><small>${Math.round(d.score)}/100 · ${esc(d.alternative_reason)}</small></div></div>`).join('')}</div></div>`;}catch(e){root.innerHTML=`<div class="empty-state">${esc(e.message)}</div>`;}
}

async function loadPlanner(){
  if(!state.meta)state.meta=await api('/meta');
  if(state.lastPreferences){const f=$('#planner-form');for(const [k,v] of Object.entries(state.lastPreferences)){const el=f.elements[k];if(el&&k!=='interests')el.value=v;}$$('input[type=checkbox]',f).forEach(x=>x.checked=state.lastPreferences.interests.includes(x.value));}
  await loadSavedTrips();
}
async function submitPlanner(form){
  const payload=formPrefs(form);if(!payload.interests.length)payload.interests=state.lastPreferences?.interests||[];state.lastPlannerPayload=payload;
  $('#planner-generate').disabled=true;$('#planner-generate').textContent='Building route…';
  try{const plan=await api('/itineraries/preview',{method:'POST',body:payload});state.lastPlan=plan;renderPlan(plan);$('#planner-result').scrollIntoView({behavior:'smooth',block:'start'});}catch(e){toast(e.message,'error');}finally{$('#planner-generate').disabled=false;$('#planner-generate').innerHTML='Generate itinerary <span>→</span>';}
}
function renderPlan(plan){
  const root=$('#planner-result');root.classList.remove('hidden');
  root.innerHTML=`<div class="results-head"><div><span class="eyebrow">YOUR ROUTE PREVIEW</span><h2>${esc(plan.title)}</h2><p>${plan.days.length} destination stops · ${plan.travellers} traveller(s) · ${esc(plan.route.source)}</p></div><div class="plan-actions"><button class="button button-primary button-small" data-action="save-plan">Save itinerary ↗</button><button class="button button-secondary button-small" data-action="print-plan">Print / PDF</button></div></div><div class="plan-result"><div class="panel"><div class="panel-head"><div><span class="eyebrow">ROUTE MAP</span><h3>Travel sequence</h3></div><span class="tag tag-muted">${esc(plan.route.source)}</span></div><div id="planner-map" class="plan-map"></div><div class="map-attribution-note">© OpenStreetMap contributors · © CARTO</div><div class="source-note" style="margin-top:9px">${esc(plan.warnings.join(' '))}</div></div><div><div class="plan-days">${plan.days.map((d,i)=>`<div class="plan-day draggable-plan-day" draggable="true" data-plan-index="${i}"><div class="plan-day-top"><span>DAY ${d.day}</span><b>${esc(d.destination)}</b><span class="plan-reorder"><button type="button" data-move-day="${i-1}" ${i===0?'disabled':''} aria-label="Move day up">↑</button><button type="button" data-move-day="${i+1}" ${i===plan.days.length-1?'disabled':''} aria-label="Move day down">↓</button></span></div><label class="field" style="margin-top:8px">Change this day<select data-plan-stop="${d.day}">${state.destinations.map(x=>`<option value="${esc(x.slug)}" ${x.slug===d.slug?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><p>${esc(d.travel_from)} · ${d.distance_km} km · approx. ${d.travel_hours} hr<br>Explore: ${esc(d.attractions.join(' · '))}</p><span class="plan-cost">${money(d.estimated_spend_per_person_inr.low)}–${money(d.estimated_spend_per_person_inr.high)} per person</span></div>`).join('')}</div><div class="panel" style="margin-top:10px;padding:15px"><span class="eyebrow">INDICATIVE TRIP BUDGET</span><h3 style="font-size:20px;color:#438778">${money(plan.total_estimate_inr.low)} – ${money(plan.total_estimate_inr.high)}</h3><p class="panel-subtext">For ${plan.travellers} traveller(s); excludes or may vary with transport, permits, seasonal pricing and availability.</p></div></div></div>`;
  renderPlanMap(plan);
}
function renderPlanMap(plan){if(!window.L)return;const el=$('#planner-map');if(!el)return;if(state.planMap){state.planMap.remove();state.planMap=null;}const map=L.map(el,{scrollWheelZoom:false});state.planMap=map;L.tileLayer('https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png',{attribution:'© OpenStreetMap contributors · © CARTO',subdomains:'abcd',maxZoom:19}).addTo(map);const points=[];const originLookup={'bengaluru':[12.9716,77.5946],'bangalore':[12.9716,77.5946],'mysuru':[12.2958,76.6394],'mysore':[12.2958,76.6394],'mangaluru':[12.9141,74.8560],'mangalore':[12.9141,74.8560],'hyderabad':[17.385,78.4867],'chennai':[13.0827,80.2707],'goa':[15.2993,74.124],'pune':[18.5204,73.8567],'mumbai':[19.076,72.8777],'kochi':[9.9312,76.2673],'delhi':[28.6139,77.209]};const origin=(originLookup[plan.origin.toLowerCase().split(',')[0].trim()]||originLookup.bengaluru);points.push(origin);const markers=[];L.marker(origin).addTo(map).bindPopup(`<b>Origin · ${esc(plan.origin)}</b>`);plan.days.forEach((d,i)=>{const found=state.destinations.find(x=>x.slug===d.slug);if(found){points.push([found.latitude,found.longitude]);markers.push(L.marker([found.latitude,found.longitude]).addTo(map).bindPopup(`<b>${esc(d.destination)}</b><br>Day ${d.day}`));}});if(plan.route.geometry){L.geoJSON(plan.route.geometry,{style:{color:'#418e7c',weight:4,opacity:.8,dashArray:plan.route.source.includes('Approximation')?'6 6':null}}).addTo(map);}if(points.length>1)map.fitBounds(points,{padding:[25,25]});else map.setView(origin,7);setTimeout(()=>map.invalidateSize(),120);}
async function saveCurrentPlan(){if(!state.lastPlan){toast('Generate a route first.','error');return;}if(!state.user){openAuth('login');toast('Sign in to save this itinerary.','error');return;}const title=prompt('Name this itinerary:',state.lastPlan?.title||'My Karnataka trip');if(title===null)return;try{const data=await api('/itineraries/save-preview',{method:'POST',body:{title,plan:state.lastPlan}});toast(data.message);await loadSavedTrips();}catch(e){toast(e.message,'error');}}
async function loadSavedTrips(){const root=$('#saved-trips-list');if(!state.user){root.className='empty-state';root.textContent='Sign in to save, retrieve and manage your itineraries.';return;}try{const d=await api('/itineraries');root.className='';root.innerHTML=d.itineraries.length?d.itineraries.map(x=>`<div class="saved-trip-row"><div><b>${esc(x.title)}</b><small>${esc(x.origin)} · ${MONTHS[x.month-1]} · ${x.days} days · ${new Date(x.created_at).toLocaleDateString()}</small></div><div><button class="text-link" data-action="view-trip" data-id="${x.id}">View</button> <button class="text-link" data-action="share-trip" data-id="${x.id}">Share ↗</button> <button class="text-link" data-action="delete-trip" data-id="${x.id}">Delete</button></div></div>`).join():'<div class="empty-state">No saved itineraries yet. Generate a route and save it here.</div>';}catch(e){root.textContent=e.message;}}


// TourInsight community and field features.
function featureTab(name){$$('[data-feature-tab]').forEach(b=>b.classList.toggle('active',b.dataset.featureTab===name));$$('.feature-pane').forEach(p=>p.classList.toggle('active',p.id==='feature-'+name));}
function renderDistricts(query=''){
  const term=query.trim().toLowerCase();
  const groups={};state.destinations.forEach(d=>{if(!term||[d.name,d.district,d.region,d.category].join(' ').toLowerCase().includes(term))(groups[d.district||'Other']??=[]).push(d);});
  const root=$('#district-cards');if(!root)return;
  root.innerHTML=Object.entries(groups).sort((a,b)=>a[0].localeCompare(b[0])).map(([district,items])=>`<button type="button" class="district-card" data-district="${esc(district)}"><span class="district-card-mark">⌖</span><span><b>${esc(district)}</b><small>${items.map(x=>esc(x.name)).join(' · ')}</small></span><strong>${items.length.toString().padStart(2,'0')}</strong></button>`).join('')||'<div class="empty-state">No matching district or destination in the current catalogue.</div>';
}
function renderCommunityMap(){const el=$('#community-map');if(!el||!window.L||state.communityMap)return;state.communityMap=L.map(el,{scrollWheelZoom:false}).setView([14.2,76.2],6);L.tileLayer('https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png',{attribution:'© OpenStreetMap contributors · © CARTO',subdomains:'abcd',maxZoom:18}).addTo(state.communityMap);state.destinations.forEach(d=>{const marker=L.marker([d.latitude,d.longitude]).addTo(state.communityMap);marker.bindPopup(`<b>${esc(d.name)}</b><br>${esc(d.district||'Karnataka')}<br><a href="#" class="map-popup-link" data-community-map-slug="${esc(d.slug)}">Open destination details ↗</a>`);marker.on('popupopen',()=>{const a=el.querySelector(`[data-community-map-slug="${d.slug}"]`);if(a)a.onclick=ev=>{ev.preventDefault();openDestinationDetail(d.slug);};});});setTimeout(()=>state.communityMap.invalidateSize(),180);}
async function loadCommunity(){await refreshDestinations();renderDistricts($('#district-search')?.value||'');renderCommunityMap();await loadCommunityFeed();if(state.user){await Promise.allSettled([loadGroups(),loadJournal(),loadPassport()]);}else{$('#group-list').innerHTML='<div class="empty-state">Sign in to create or join a group. You can still browse community stories.</div>';$('#journal-list').innerHTML='<div class="empty-state">Sign in to keep a personal travel journal.</div>';$('#challenge-list').innerHTML='<div class="empty-state">Sign in to track your travel milestones.</div>';$('#passport-count').innerHTML='— <small>sign in to track visits</small>';$('#passport-stamps').innerHTML='';}loadTransport($('#transport-destination')?.value||state.destinations[0]?.slug);if(state.communityMap)setTimeout(()=>state.communityMap.invalidateSize(),160);}
async function loadCommunityFeed(){const root=$('#community-feed');if(!root)return;try{const d=await api('/community/posts');root.innerHTML=d.posts.length?d.posts.map(p=>`<article class="community-post"><div class="post-meta"><span class="post-type">${esc(nice(p.post_type))}</span><span>${esc(p.author)} · ${esc(new Date(p.created_at+'Z').toLocaleDateString())}</span></div><h3>${esc(p.title)}</h3>${p.destination?`<div class="post-destination">⌖ ${esc(p.destination)}</div>`:''}<p>${esc(p.body)}</p>${p.image_url?`<img class="post-photo" src="${esc(p.image_url)}" alt="Travel photo shared by ${esc(p.author)}" loading="lazy">`:''}</article>`).join(''):'<div class="empty-state">No stories yet. Be the first to share a useful travel tip.</div>';}catch(e){root.innerHTML=`<div class="empty-state">${esc(e.message)}</div>`;}}
async function loadGroups(){const root=$('#group-list');if(!state.user){root.textContent='Sign in to view your groups.';return;}try{const d=await api('/groups');root.innerHTML=d.groups.length?d.groups.map(g=>`<div class="group-board-wrap"><div class="group-row"><div><b>${esc(g.name)}</b><small>${g.member_count} member(s) · Created ${esc(g.created_at)}</small>${g.itinerary_id?'<small>Saved itinerary attached</small>':''}<button class="text-link" type="button" data-open-group="${g.id}">Open collaborative board ↓</button></div><div class="invite-code"><small>INVITE CODE</small><strong>${esc(g.invite_code)}</strong><button type="button" data-copy-code="${esc(g.invite_code)}">Copy</button></div></div><div class="group-board hidden" id="group-board-${g.id}"></div></div>`).join(''):'<div class="empty-state">No trip groups yet. Create one or join with an invite code.</div>';const trips=await api('/itineraries');$('#group-itinerary').innerHTML='<option value="">No itinerary attached</option>'+trips.itineraries.map(t=>`<option value="${t.id}">${esc(t.title)}</option>`).join('');}catch(e){root.textContent=e.message;}}
async function loadGroupBoard(groupId){const root=$('#group-board-'+groupId);if(!root)return;root.classList.remove('hidden');root.innerHTML='<div class="empty-state">Loading group ideas…</div>';try{const d=await api('/groups/'+groupId+'/suggestions');root.innerHTML=`<div class="group-board-head"><b>Shared destination shortlist</b><span>${d.suggestions.length} idea(s)</span></div><div class="group-suggestions">${d.suggestions.map(x=>`<div class="group-suggestion"><div><b>${esc(x.destination)}</b><small>Suggested by ${esc(x.author)} · ${esc(x.note||'No note added')}</small></div><button type="button" data-vote-suggestion="${x.id}" data-group-id="${groupId}" class="vote-button ${x.voted?'voted':''}">♥ ${x.votes} ${x.voted?'Voted':'Vote'}</button></div>`).join('')||'<p class="form-hint">No suggestions yet. Add the first place for the group to consider.</p>'}</div><form class="group-suggest-form" data-group-suggest-form="${groupId}"><label class="field">Suggest a destination<select name="destination_slug">${state.destinations.map(x=>`<option value="${esc(x.slug)}">${esc(x.name)}</option>`).join('')}</select></label><label class="field">Why should the group go?<input name="note" maxlength="500" placeholder="Good for a two-day weekend…"></label><button class="button button-primary button-small" type="submit">Add to shortlist +</button></form>`;}catch(e){root.innerHTML=`<div class="empty-state">${esc(e.message)}</div>`;}}
async function loadJournal(){const root=$('#journal-list');if(!state.user){root.textContent='Sign in to save journal entries.';return;}try{const d=await api('/journal');root.innerHTML=d.entries.length?d.entries.map(j=>`<article class="journal-entry">${j.image_url?`<img src="${esc(j.image_url)}" alt="${esc(j.title)}">`:''}<div><span class="eyebrow">${esc(j.destination||'TRAVEL NOTE')} · ${esc(j.visit_date||'Date not set')}</span><h3>${esc(j.title)}</h3><p>${esc(j.notes)}</p><button class="text-link" data-delete-journal="${j.id}">Delete entry</button></div></article>`).join(''):'<div class="empty-state">Your journal is waiting for its first story.</div>';}catch(e){root.textContent=e.message;}}
async function loadPassport(){const d=await api('/challenges');$('#passport-count').innerHTML=`${d.visited_count} <small>unique destinations visited</small>`;$('#passport-stamps').innerHTML=d.checkins.length?d.checkins.map(c=>`<span class="passport-stamp" title="${esc(c.visited_on)}">✦<small>${esc(state.destinations.find(x=>x.slug===c.destination_slug)?.name||c.destination_slug)}</small></span>`).join(''):'<span class="passport-empty">Your first stamp is waiting.</span>';$('#challenge-list').innerHTML=d.challenges.map(c=>`<div class="challenge-row"><div><b>${esc(c.name)}</b><small>${esc(c.description)}</small><div class="challenge-track"><i style="width:${Math.round(c.progress/c.target*100)}%"></i></div></div><strong>${c.progress}/${c.target}${c.progress>=c.target?' ✓':''}</strong></div>`).join('');}
async function loadTransport(slug){const root=$('#transport-options');if(!root||!slug)return;try{const d=await api('/transport/'+encodeURIComponent(slug));root.innerHTML=d.links.map(x=>`<a class="transport-option" href="${esc(x.url)}" target="_blank" rel="noopener"><span>${esc(x.mode)}</span><b>${esc(x.provider)}</b><strong>↗</strong></a>`).join('')+`<p class="form-hint">${esc(d.note)}</p>`;}catch(e){root.textContent=e.message;}}
async function movePlanStop(from,to){if(!state.lastPlan||to<0||to>=state.lastPlan.days.length||from===to)return;const stops=state.lastPlan.days.map(x=>x.slug);const [moved]=stops.splice(from,1);stops.splice(to,0,moved);try{const p=await api('/itineraries/custom-preview',{method:'POST',body:{origin:state.lastPlan.origin||'Bengaluru',month:state.lastPlan.month||new Date().getMonth()+1,travellers:state.lastPlan.travellers||1,destination_slugs:stops}});state.lastPlan=p;renderPlan(p);toast('Trip sequence updated.');}catch(e){toast(e.message,'error');}}
const LANGS={en:{overview:'Overview',explore:'Destination explorer',smartseason:'SmartSeason',planner:'Trip planner',toolkit:'Travel toolkit',community:'Travel community',fieldguide:'Stays & experiences',analytics:'Tourism analytics',sentiment:'Visitor experience',forecast:'Popularity forecast',pressure:'Pressure & opportunity',quality:'Data quality'},kn:{overview:'ಅವಲೋಕನ',explore:'ತಾಣಗಳನ್ನು ಅನ್ವೇಷಿಸಿ',smartseason:'ಸ್ಮಾರ್ಟ್ ಸೀಸನ್',planner:'ಪ್ರಯಾಣ ಯೋಜನೆ',toolkit:'ಪ್ರಯಾಣ ಸಾಧನಗಳು',community:'ಪ್ರಯಾಣ ಸಮುದಾಯ',analytics:'ಪ್ರವಾಸೋದ್ಯಮ ವಿಶ್ಲೇಷಣೆ',sentiment:'ಪ್ರವಾಸಿ ಅನುಭವ',forecast:'ಜನಪ್ರಿಯತೆ ಮುನ್ಸೂಚನೆ',pressure:'ಒತ್ತಡ ಮತ್ತು ಅವಕಾಶ',quality:'ಡೇಟಾ ಗುಣಮಟ್ಟ'},hi:{overview:'अवलोकन',explore:'स्थल खोजें',smartseason:'स्मार्ट सीज़न',planner:'यात्रा योजना',toolkit:'यात्रा टूलकिट',community:'यात्रा समुदाय',analytics:'पर्यटन विश्लेषण',sentiment:'यात्री अनुभव',forecast:'लोकप्रियता पूर्वानुमान',pressure:'दबाव और अवसर',quality:'डेटा गुणवत्ता'}};
function applyLanguage(lang){const dict=LANGS[lang]||LANGS.en;$$('.nav-item[data-page]').forEach(b=>{const page=b.dataset.page,icon=b.querySelector('.nav-icon')?.outerHTML||'';b.innerHTML=icon+' '+(dict[page]||LANGS.en[page]||page);});const status=$('#language-status');if(status)status.textContent=lang==='kn'?'ಕೆಲವು ನ್ಯಾವಿಗೇಷನ್ ಲೇಬಲ್‌ಗಳನ್ನು ಕನ್ನಡಕ್ಕೆ ಬದಲಾಯಿಸಲಾಗಿದೆ.':lang==='hi'?'कुछ नेविगेशन लेबल हिन्दी में बदल दिए गए हैं।':'English interface selected.';localStorage.setItem('tourinsight_language',lang);}

async function loadAnalytics(){
  const d=await api('/dashboard');state.dashboard=d;
  $('#analytics-kpis').innerHTML=[formatKpi('Destinations',d.kpis.destinations,'Active destination records','⌖'),formatKpi('Visitor records',d.kpis.tourism_records,'Monthly rows imported','▥'),formatKpi('Reviews',d.kpis.review_count,'Collected feedback records','♡'),formatKpi('Average rating',d.kpis.avg_rating??'—',d.kpis.avg_rating?'Stored rating average':'No stored ratings','★')].join();
  const allYears=[...new Set(d.monthly_tourism.map(x=>x.year))].sort();$('#analytics-year').innerHTML='<option value="all">All available years</option>'+allYears.map(y=>`<option value="${y}">${y}</option>`).join();$('#analytics-destination').innerHTML='<option value="all">All destinations</option>'+state.destinations.map(x=>`<option value="${esc(x.slug)}">${esc(x.name)}</option>`).join();
  await renderAnalyticsCharts(d);
  $('#popularity-table').innerHTML=`<table><thead><tr><th>Destination</th><th>Category</th><th>Discoverability index</th><th>Visitor rating</th><th>Opportunity</th></tr></thead><tbody>${d.popularity_ranking.map(x=>`<tr><td><b>${esc(x.name)}</b></td><td>${esc(x.category)}</td><td><span class="table-score">${x.popularity_index??'—'}</span></td><td>${x.rating?`★ ${x.rating.avg} (${x.rating.count})`:'Not available'}</td><td>${x.opportunity.score===null?'—':`${x.opportunity.score}/100 · ${x.opportunity.coverage}% coverage`}</td></tr>`).join('')}</tbody></table>`;
  $('#source-cards').innerHTML=d.sources.slice(0,6).map(s=>`<div class="source-mini"><b>${esc(s.name)}</b><small>${esc(s.status)}</small><span class="source-status ${s.status.toLowerCase().includes('manual')||s.status.toLowerCase().includes('not connected')?'off':''}">${esc(s.category)}</span></div>`).join();
}
const PACKING_TEMPLATES={
  general:[['Documents','Government ID / driving licence'],['Documents','Hotel and transport confirmations'],['Essentials','Wallet, cards and some cash'],['Essentials','Phone and charger'],['Essentials','Power bank'],['Clothing','Comfortable outfits'],['Clothing','Sleepwear and undergarments'],['Health','Personal medication'],['Health','Basic first-aid kit'],['Personal care','Toiletries and sunscreen'],['Extras','Reusable water bottle'],['Extras','Small day bag']],
  hill:[['Documents','Government ID / driving licence'],['Clothing','Warm layers / light jacket'],['Clothing','Comfortable trekking shoes'],['Clothing','Extra socks'],['Health','Personal medication'],['Health','Insect repellent'],['Health','Sunscreen'],['Essentials','Torch / headlamp'],['Essentials','Power bank'],['Extras','Reusable water bottle'],['Extras','Rain protection'],['Extras','Small day bag']],
  beach:[['Documents','Government ID'],['Clothing','Swimwear'],['Clothing','Light clothing'],['Clothing','Extra towel'],['Health','Sunscreen'],['Health','After-sun lotion'],['Essentials','Waterproof phone pouch'],['Essentials','Reusable water bottle'],['Extras','Slippers / sandals'],['Extras','Hat and sunglasses']],
  wildlife:[['Documents','Government ID and permits'],['Clothing','Neutral-coloured comfortable clothing'],['Clothing','Closed shoes'],['Health','Insect repellent'],['Health','Personal medication'],['Essentials','Binoculars'],['Essentials','Camera and spare battery'],['Essentials','Torch'],['Extras','Reusable water bottle'],['Extras','Small day bag']],
  heritage:[['Documents','Government ID'],['Clothing','Comfortable walking shoes'],['Clothing','Light modest clothing'],['Health','Sunscreen'],['Health','Personal medication'],['Essentials','Phone and charger'],['Essentials','Power bank'],['Extras','Reusable water bottle'],['Extras','Small day bag'],['Extras','Offline map / saved directions']]
};
function loadToolkit(){
  const dest=$('#budget-destination');if(dest&&!dest.options.length){dest.innerHTML=state.destinations.map(d=>`<option value="${esc(d.slug)}">${esc(d.name)} · ${esc(d.district||'')}</option>`).join('');}
  $('#season-month').innerHTML=monthOptions();
  $('#season-category').innerHTML='<option value="all">All experiences</option>'+(state.meta?.categories||[]).map(c=>`<option value="${esc(c)}">${esc(c)}</option>`).join('');
  if(!state.packingItems){state.packingItems=PACKING_TEMPLATES.general.map((x,i)=>({id:'p'+i,category:x[0],label:x[1],checked:false}));savePacking();}
  calcBudget();renderSavedEstimates();renderPacking();loadSeasonalGuide().catch(e=>toast('Season guide could not load: '+e.message,'error'));
}
function budgetInputs(){const val=id=>Math.max(0,Number($('#'+id)?.value)||0);return {destination:$('#budget-destination')?.value||'',days:Math.min(30,Math.max(1,val('budget-days'))),people:Math.min(20,Math.max(1,val('budget-people'))),transport:val('cost-transport'),stay:val('cost-stay'),rooms:Math.min(10,Math.max(1,val('cost-rooms'))),food:val('cost-food'),activities:val('cost-activities'),other:val('cost-other'),buffer:Math.min(30,val('cost-buffer'))};}
function budgetCalc(){const x=budgetInputs(),base=[{name:'Transport',value:x.transport},{name:'Accommodation',value:x.stay*x.rooms*Math.max(0,x.days-1)},{name:'Food',value:x.food*x.people*x.days},{name:'Activities',value:x.activities*x.people},{name:'Other',value:x.other}];const subtotal=base.reduce((a,b)=>a+b.value,0),reserve=subtotal*x.buffer/100,total=subtotal+reserve;return {inputs:x,lines:[...base,{name:`Contingency (${x.buffer}%)`,value:reserve}],subtotal,reserve,total,perPerson:total/x.people,perDay:total/x.days};}
function calcBudget(){if(!$('#budget-total'))return;const d=budgetCalc();$('#budget-total').textContent=money(d.total);$('#budget-per-person').textContent=money(d.perPerson)+' / person';$('#budget-daily').textContent=money(d.perDay)+' / day';$('#contingency-label').textContent=d.inputs.buffer+'%';const max=Math.max(1,...d.lines.map(x=>x.value));$('#budget-breakdown').innerHTML=d.lines.map(x=>`<div class="budget-line"><div><span>${esc(x.name)}</span><b>${money(x.value)}</b></div><i><span style="width:${Math.max(0,x.value/max*100)}%"></span></i></div>`).join('');$('#budget-meter-fill').style.width=Math.min(100,d.inputs.buffer?100-d.inputs.buffer:100)+'%';$('#budget-range-note').textContent=`Before contingency: ${money(d.subtotal)} · Contingency reserve: ${money(d.reserve)}. Planning estimate only.`;}
function getEstimates(){try{return JSON.parse(localStorage.getItem('tourinsight_budget_estimates')||'[]')}catch{return []}}
function saveEstimate(){const d=budgetCalc(),name=state.destinations.find(x=>x.slug===d.inputs.destination)?.name||'Trip estimate';const list=getEstimates();list.unshift({id:Date.now(),name,created:new Date().toLocaleDateString('en-IN'),...d});localStorage.setItem('tourinsight_budget_estimates',JSON.stringify(list.slice(0,8)));renderSavedEstimates();$('#budget-message').textContent='Estimate saved in this browser.';toast('Budget estimate saved.');}
function renderSavedEstimates(){const list=getEstimates();$('#estimate-count').textContent=`${list.length} saved`;$('#saved-estimates-list').innerHTML=list.length?list.map(x=>`<div class="saved-estimate-row"><div><b>${esc(x.name)}</b><small>${x.inputs.days} days · ${x.inputs.people} traveller(s) · ${esc(x.created)}</small></div><strong>${money(x.total)}</strong><div><button type="button" data-estimate-load="${x.id}">Load</button><button type="button" data-estimate-delete="${x.id}" aria-label="Delete estimate">×</button></div></div>`).join(''):'<p class="empty-hint">Save an estimate to keep it here.</p>';}
function loadEstimate(id){const x=getEstimates().find(v=>v.id===Number(id));if(!x)return;const i=x.inputs;const fields={'budget-destination':i.destination,'budget-days':i.days,'budget-people':i.people,'cost-transport':i.transport,'cost-stay':i.stay,'cost-rooms':i.rooms,'cost-food':i.food,'cost-activities':i.activities,'cost-other':i.other,'cost-buffer':i.buffer};Object.entries(fields).forEach(([k,v])=>{if($('#'+k))$('#'+k).value=v;});calcBudget();toast('Saved estimate loaded.');}
function exportBudget(){const d=budgetCalc(),rows=[['Cost item','Amount INR'],...d.lines.map(x=>[x.name,Math.round(x.value)]),['TOTAL',Math.round(d.total)],['PER PERSON',Math.round(d.perPerson)]];downloadCSV('tourinsight-budget.csv',rows);}
function downloadCSV(filename,rows){const csv=rows.map(r=>r.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(',')).join('\r\n');const blob=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=filename;a.click();URL.revokeObjectURL(a.href);}
async function loadSeasonalGuide(){const month=Number($('#season-month').value||new Date().getMonth()+1),category=$('#season-category').value||'all';const rows=await Promise.all(state.destinations.map(async d=>{try{if(!state.seasonalData[d.slug]){const x=await api('/destinations/'+encodeURIComponent(d.slug));state.seasonalData[d.slug]=x.seasonal||[];}const s=state.seasonalData[d.slug].find(x=>Number(x.month)===month);return {...d,score:s?.score??null,label:s?.label||'No month score',basis:s?.basis||''};}catch{return {...d,score:null,label:'Unavailable'};}}));const filtered=rows.filter(d=>category==='all'||d.category===category).sort((a,b)=>(b.score??-1)-(a.score??-1));$('#season-result-count').textContent=`${filtered.length} destinations · ${MONTHS[month-1]}`;$('#season-finder-results').innerHTML=filtered.map((d,i)=>`<article class="season-place-card"><div class="season-place-rank">${String(i+1).padStart(2,'0')}</div><img src="${esc(d.image_url)}" alt="${esc(d.name)}" loading="lazy"><div class="season-place-copy"><span class="eyebrow">${esc(d.category)} · ${esc(d.district||'Karnataka')}</span><h3>${esc(d.name)}</h3><p>${esc(d.season_note||d.description||'Explore local conditions before travel.')}</p><button class="text-link" type="button" data-action="destination-detail" data-slug="${esc(d.slug)}">View destination →</button></div><div class="season-score"><b>${d.score===null?'—':Math.round(d.score)}</b><small>/ 100</small><span>${esc(d.label)}</span></div></article>`).join('');}
function savePacking(){localStorage.setItem('tourinsight_packing',JSON.stringify(state.packingItems));}
function renderPacking(){const items=state.packingItems||[],done=items.filter(x=>x.checked).length,pct=items.length?Math.round(done/items.length*100):0;$('#packing-progress-text').textContent=pct+'%';$('#packing-progress-ring').textContent=pct+'%';$('#packing-progress-fill').style.width=pct+'%';const list=items.filter(x=>state.packingFilter==='all'||(state.packingFilter==='checked'?x.checked:!x.checked));$('#packing-list').innerHTML=list.length?list.map(x=>`<label class="packing-item ${x.checked?'packed':''}"><input type="checkbox" data-pack-check="${esc(x.id)}" ${x.checked?'checked':''}><span>${esc(x.label)}</span><small>${esc(x.category)}</small><button type="button" data-pack-delete="${esc(x.id)}" aria-label="Remove ${esc(x.label)}">×</button></label>`).join(''):'<p class="empty-hint">Nothing in this view. Nice work.</p>';$$('[data-pack-filter]').forEach(b=>b.classList.toggle('active',b.dataset.packFilter===state.packingFilter));}
function applyPackingTemplate(key){if(!PACKING_TEMPLATES[key])return;if(!confirm('Replace your current checklist with this trip starter?'))return;state.packingItems=PACKING_TEMPLATES[key].map((x,i)=>({id:key+'-'+Date.now()+'-'+i,category:x[0],label:x[1],checked:false}));savePacking();renderPacking();toast('Packing list updated.');}
function exportPacking(){downloadCSV('tourinsight-packing-checklist.csv',[['Packed','Category','Item'],...state.packingItems.map(x=>[x.checked?'Yes':'No',x.category,x.label])]);}
function switchTool(tab){$$('[data-tool-tab]').forEach(b=>b.classList.toggle('active',b.dataset.toolTab===tab));$$('.tool-pane').forEach(p=>p.classList.toggle('active',p.id==='tool-'+tab));}

async function renderAnalyticsCharts(d){
  const selected=$('#analytics-destination').value;const year=$('#analytics-year').value;
  const params=new URLSearchParams();if(selected!=='all')params.set('destination',selected);if(year!=='all')params.set('year',year);
  const series=await api('/analytics/tourism-series?'+params.toString());
  const rows=series.rows||[];const aggregate={};rows.forEach(x=>{const key=`${x.year}-${String(x.month).padStart(2,'0')}`;aggregate[key]=(aggregate[key]||0)+x.visitors;});
  const keys=Object.keys(aggregate).sort();const empty=keys.length===0;
  $('#tourism-chart-empty').classList.toggle('hidden',!empty);$('#tourism-trend-chart').classList.toggle('hidden',empty);
  if(empty){$('#tourism-chart-empty').textContent=selected!=='all'?'No visitor series is available for this destination and year filter.':'No destination visitor time series yet. Import an official or properly licensed monthly tourism CSV in the Admin Console to activate this chart.';}
  else{chart('tourism-trend-chart',{type:'line',data:{labels:keys,datasets:[{label:`Imported monthly visitors · ${series.scope}`,data:keys.map(k=>aggregate[k]),borderColor:'#418d7c',backgroundColor:'rgba(65,141,124,.13)',fill:true,tension:.3,pointRadius:2}]},options:clone(chartDefaults)});}
  chart('seasonality-chart',{type:'bar',data:{labels:MONTHS.map(x=>x.slice(0,3)),datasets:[{label:'Average suitability',data:d.seasonality.map(x=>x.score),backgroundColor:'#9bbfae',borderRadius:5,maxBarThickness:22}]},options:{...clone(chartDefaults),plugins:{...chartDefaults.plugins,legend:{display:false}},scales:{...chartDefaults.scales,y:{...chartDefaults.scales.y,min:0,max:100}}}});
}

async function loadSentiment(){const d=await api('/sentiment');renderSentiment(d);await refreshDestinations();}
function renderSentiment(d){
  const root=$('#sentiment-overview');if(!d.available){root.innerHTML=[formatKpi('Reviews',0,'No feedback collected','♡'),formatKpi('Positive',0,'Awaiting text feedback','↗'),formatKpi('Negative',0,'Awaiting text feedback','↘'),formatKpi('Average rating','—','No submitted ratings','★')].join();$('#sentiment-empty').classList.remove('hidden');$('#sentiment-empty').textContent=d.message;$('#sentiment-chart').classList.add('hidden');$('#aspect-chart').style.display='none';$('#review-list').innerHTML='<div class="empty-state">No reviews are currently available.</div>';return;}
  $('#aspect-chart').style.display='block';root.innerHTML=[formatKpi('Reviews analysed',d.total,'User or imported feedback','♡'),formatKpi('Positive',d.sentiments.positive||0,'Keyword baseline sentiment','↗'),formatKpi('Negative',d.sentiments.negative||0,'Keyword baseline sentiment','↘'),formatKpi('Average rating',d.average_rating??'—','Stored ratings out of 5','★')].join();$('#sentiment-empty').classList.add('hidden');$('#sentiment-chart').classList.remove('hidden');
  chart('sentiment-chart',{type:'doughnut',data:{labels:['Positive','Neutral','Negative'],datasets:[{data:[d.sentiments.positive||0,d.sentiments.neutral||0,d.sentiments.negative||0],backgroundColor:['#71a88d','#d6dfd8','#c98678'],borderWidth:0,hoverOffset:5}]},options:{responsive:true,maintainAspectRatio:false,cutout:'68%',plugins:chartDefaults.plugins}});
  const aspects=Object.entries(d.aspects||{}).sort((a,b)=>b[1]-a[1]);chart('aspect-chart',{type:'bar',data:{labels:aspects.map(x=>nice(x[0])),datasets:[{label:'Mentions',data:aspects.map(x=>x[1]),backgroundColor:'#96b7a8',borderRadius:4}]},options:{...clone(chartDefaults),indexAxis:'y',plugins:{...chartDefaults.plugins,legend:{display:false}},scales:{x:chartDefaults.scales.x,y:{grid:{display:false},ticks:{color:'#82918b',font:{size:8}}}}}});
  $('#review-list').innerHTML=d.reviews.map(r=>`<div class="review-row"><div class="review-row-top"><b>${esc(r.destination)} · ${esc(r.author)}</b><span>${r.rating?`★ ${r.rating}/5`:'No rating'} · ${esc(nice(r.sentiment))}</span></div><p>${esc(r.text)}</p>${r.image_url?`<img class="review-photo-thumb" src="${esc(r.image_url)}" alt="Photo attached to visitor review" loading="lazy">`:''}<small>${esc(r.source)} · ${esc(r.date)} · ${r.aspects.map(nice).join(', ')}</small></div>`).join();
}

async function loadForecast(){const d=await api('/predictions');renderForecast(d);}
function renderForecast(d){const root=$('#forecast-content');if(!d.available_count){root.innerHTML=`<div class="empty-state" style="grid-column:1/-1"><b>Forecasting is not active yet.</b><br>${esc(d.message||'Import at least 24 monthly visitor observations for a destination.')}<br><br><button class="button button-secondary button-small" data-page="admin">Open data imports ↗</button></div>`;return;}
  root.innerHTML=d.destinations.filter(x=>x.available).map(x=>`<div class="forecast-card"><div class="eyebrow">${x.observations} MONTHLY OBSERVATIONS</div><h3>${esc(x.name)}</h3><p>Selected model: ${esc(x.model)} · ${esc(x.evaluation)}</p><div class="forecast-metrics"><div class="forecast-metric"><b>${money(x.model_scores[x.model].mae)}</b><small>MAE · holdout</small></div><div class="forecast-metric"><b>${money(x.model_scores[x.model].rmse)}</b><small>RMSE · holdout</small></div></div><canvas id="forecast-${esc(x.slug)}" class="chart-canvas"></canvas><div class="table-wrap"><table><thead><tr><th>Forecast month</th><th>Estimated visits</th></tr></thead><tbody>${x.forecast.map(f=>`<tr><td>${MONTHS[f.month-1]} ${f.year}</td><td>${Math.round(f.predicted_visitors).toLocaleString('en-IN')}</td></tr>`).join('')}</tbody></table></div></div>`).join();
  d.destinations.filter(x=>x.available).forEach(x=>{const labels=x.history.map(r=>`${MONTHS[r.month-1].slice(0,3)} ${r.year}`).concat(x.forecast.map(r=>`${MONTHS[r.month-1].slice(0,3)} ${r.year}`));chart('forecast-'+x.slug,{type:'line',data:{labels,datasets:[{label:'Historical visitors',data:x.history.map(r=>r.visitors).concat([null,null,null]),borderColor:'#4d907f',tension:.2,pointRadius:1},{label:'Model estimate',data:Array(x.history.length-1).fill(null).concat([x.history[x.history.length-1].visitors],x.forecast.map(f=>f.predicted_visitors)),borderColor:'#c29854',borderDash:[5,4],tension:.2,pointRadius:2}]},options:clone(chartDefaults)});});
}

async function loadPressure(){const d=state.dashboard||await api('/dashboard');state.dashboard=d;renderPressure(d);}
function renderPressure(d){const items=d.popularity_ranking;$('#opportunity-grid').innerHTML=items.map(x=>`<div class="opportunity-card"><div class="opportunity-card-top"><b>${esc(x.name)}</b><span class="opportunity-number">${x.opportunity.score===null?'—':x.opportunity.score}</span></div><div class="opportunity-bar"><span style="width:${Math.max(0,Math.min(100,x.opportunity.score||0))}%"></span></div><small>Opportunity score · ${x.opportunity.coverage}% input coverage · ${esc(x.trend.label||'Trend unavailable')}${x.trend.change_pct!==undefined?' ('+x.trend.change_pct+'%)':''}</small><div class="quality-notes" style="margin-top:8px">${Object.entries(x.opportunity.components).map(([k,v])=>`<div class="quality-note"><span>·</span>${esc(nice(k))}: ${v===null?'Not available':Math.round(v)+'/100'}</div>`).join('')}</div></div>`).join();
  $('#pressure-table').innerHTML=`<table><thead><tr><th>Destination</th><th>Latest visitor record</th><th>Capacity baseline</th><th>Pressure</th><th>Popularity trend</th><th>Data note</th></tr></thead><tbody>${items.map(x=>`<tr><td><b>${esc(x.name)}</b></td><td>${x.pressure.visitors===undefined?'—':Math.round(x.pressure.visitors).toLocaleString('en-IN')}</td><td>${x.pressure.capacity?Math.round(x.pressure.capacity).toLocaleString('en-IN'):'—'}</td><td><span class="pressure-cell ${x.pressure.label==='High'?'high':x.pressure.label==='Moderate'?'mid':''}">${esc(x.pressure.label)}</span></td><td>${x.trend.available?`${esc(x.trend.label)} · ${x.trend.change_pct}%`:'Not enough history'}</td><td>${x.pressure.available?`${x.pressure.year}/${x.pressure.month} · imported data`:'Insufficient visitor and/or capacity data'}</td></tr>`).join('')}</tbody></table>`;
}

async function loadQuality(){const d=await api('/quality');$('#quality-kpis').innerHTML=[formatKpi('Quality indicator',d.summary.quality_score+' / 100','Completeness and consistency proxy','◈'),formatKpi('Destination records',d.summary.destinations,'Active catalogue records','⌖'),formatKpi('Tourism records',d.summary.tourism_records,'Monthly visitor observations','▥'),formatKpi('Review records',d.summary.reviews,'Stored feedback rows','♡')].join();const s=await api('/sources');$('#quality-sources').innerHTML=s.sources.map(sourceRow).join('');$('#quality-notes').innerHTML=d.notes.map(x=>`<div class="quality-note"><span>✦</span>${esc(x)}</div>`).join();$('#quality-detail').textContent=state.user?.role==='admin'?'Generate a detailed report in the Admin Console to inspect row-level quality issues.':'Sign in as an administrator to inspect row-level data-quality issues and generate a report.';}
function sourceRow(s){return `<div class="source-row"><div><b>${esc(s.name)}</b><small>${esc(s.notes||'')}</small><small>Reliability: ${esc(s.reliability||'Not assessed')} · Attribution: ${esc(s.attribution||'Not supplied')}</small>${s.url?`<small><a href="${esc(s.url)}" target="_blank" rel="noopener">Open source ↗</a></small>`:''}</div><span class="tag ${/manual|not connected|reference link/i.test(s.status)?'tag-warn':'tag-green'}">${esc(s.status)}</span></div>`;}

async function loadAdmin(){if(!state.user||state.user.role!=='admin'){showPage('overview');toast('Administrator access is required.','error');return;}await loadAdminTab(state.adminTab);}
async function loadAdminTab(tab){state.adminTab=tab;$$('.admin-tab').forEach(b=>b.classList.toggle('active',b.dataset.adminTab===tab));$$('.admin-pane').forEach(p=>p.classList.toggle('active',p.id==='admin-'+tab));
  if(tab==='imports'){loadAdminActivity();loadDataGovStatus();}if(tab==='weights')loadWeightEditor();if(tab==='destinations')loadAdminDestinations();if(tab==='users')loadAdminUsers();if(tab==='sources')loadAdminSources();if(tab==='quality')loadAdminQuality();}
async function loadAdminActivity(){try{const d=await api('/admin/activity');$('#admin-activity-grid').innerHTML=[formatKpi('Registered users',d.users,'Local TourInsight accounts','♙'),formatKpi('Active logins',d.users_logged_in,'Users who have logged in','↗'),formatKpi('Recommendation runs',d.recommendation_runs,'Saved recommendation requests','✧'),formatKpi('Saved itineraries',d.saved_itineraries,'Stored trip plans','⌑')].join();}catch(e){toast(e.message,'error');}}
async function loadDataGovStatus(){
  const status=$('#data-gov-status'),tag=$('#data-gov-tag'),button=$('#sync-data-gov-in');
  try{
    const d=await api('/admin/connectors/data-gov-in/status');
    const m=d.field_mapping||{};
    tag.textContent=d.configured?'Connector configured':'Setup required';
    tag.className='tag '+(d.configured?'tag-green':'tag-warn');
    button.disabled=!d.configured;
    status.innerHTML=d.configured
      ? `<div class="quality-note"><span>✓</span><b>Resource configured:</b> ${esc(d.resource_id)}</div><div class="quality-note"><span>↳</span><b>API key:</b> present on local server; not exposed to this page.</div><div class="quality-note"><span>⌘</span><b>Column mapping:</b> ${Object.entries(m).map(([k,v])=>`${esc(k)} → ${esc(v)}`).join(' · ')}</div>`
      : `<div class="quality-note"><span>!</span><b>Not connected yet.</b> Add <code>DATA_GOV_IN_API_KEY</code> and <code>DATA_GOV_IN_RESOURCE_ID</code> to your local <code>.env</code> file, verify the field mapping, then restart TourInsight.</div><div class="quality-note"><span>↳</span>Get an API key and select a dataset resource on the official data.gov.in portal. A resource-specific ID and schema are required; TourInsight does not guess a dataset.</div>`;
  }catch(e){tag.textContent='Status unavailable';tag.className='tag tag-warn';button.disabled=true;status.textContent=e.message;}
}
async function loadWeightEditor(){const d=await api('/admin/weights');const root=$('#weight-editor-rows');root.innerHTML=d.weights.map(w=>`<div class="weight-edit-row"><b>${esc(w.label)}</b><input type="range" min="0" max="100" step="1" data-weight-range="${esc(w.key)}" value="${w.value}"><input type="number" min="0" max="100" step="1" data-weight-number="${esc(w.key)}" value="${w.value}"></div>`).join();updateWeightTotal();}
function updateWeightTotal(){const vals=$$('[data-weight-number]').map(x=>Number(x.value)||0);const sum=vals.reduce((a,b)=>a+b,0);$('#weight-total').textContent=sum+'%';$('#weight-total').style.color=Math.abs(sum-100)<.01?'#438778':'#b66a54';}
async function loadAdminDestinations(){const d=await api('/admin/destinations');$('#admin-dest-table').innerHTML=`<table><thead><tr><th>Destination</th><th>District</th><th>Region</th><th>Active</th><th>Monthly capacity</th><th>Action</th></tr></thead><tbody>${d.destinations.map(x=>`<tr><td><b>${esc(x.name)}</b></td><td>${esc(x.district||'')}</td><td>${esc(x.region||'')}</td><td>${x.active?'Active':'Paused'}</td><td>${x.capacity_per_month??'Not recorded'}</td><td><button class="text-link" data-action="edit-destination" data-slug="${esc(x.slug)}">Edit capacity / status</button></td></tr>`).join('')}</tbody></table>`;}
async function loadAdminUsers(){const d=await api('/admin/users');$('#admin-users-table').innerHTML=d.users.length?`<table><thead><tr><th>Name</th><th>Email</th><th>Origin</th><th>Joined</th><th>Role</th></tr></thead><tbody>${d.users.map(x=>`<tr><td><b>${esc(x.full_name)}</b></td><td>${esc(x.email)}</td><td>${esc(x.origin||'—')}</td><td>${esc(x.created_at)}</td><td><select data-user-role="${x.id}" ${x.id===state.user.id?'disabled':''}><option value="tourist" ${x.role==='tourist'?'selected':''}>Tourist</option><option value="admin" ${x.role==='admin'?'selected':''}>Admin</option></select></td></tr>`).join('')}</tbody></table>`:'<div class="empty-state">No registered users yet.</div>';}
async function loadAdminSources(){const d=await api('/admin/sources');$('#admin-source-list').innerHTML=d.sources.map(sourceRow).join();}
async function loadAdminQuality(){const el=$('#admin-quality-report');el.innerHTML='<div class="empty-state">Click “Generate report” to inspect the current database.</div>';}
async function runAdminQuality(){const d=await api('/admin/quality');$('#admin-quality-report').innerHTML=`<div class="kpi-grid">${formatKpi('Quality proxy',d.summary.quality_score+'/100','Completeness and consistency','◈')}${formatKpi('Destinations',d.summary.destinations,'Reference records','⌖')}${formatKpi('Visitor records',d.summary.tourism_records,'Imported monthly rows','▥')}${formatKpi('Review records',d.summary.reviews,'Stored feedback','♡')}</div><div class="quality-notes">${d.notes.map(n=>`<div class="quality-note"><span>✦</span>${esc(n)}</div>`).join()}</div><h4 style="margin-top:18px">Detailed checks</h4><pre class="quality-json">${esc(JSON.stringify(d.checks,null,2))}</pre>`;}

function showModal(html,detail=false){$('#modal-content').innerHTML=html;$('#modal-backdrop').classList.remove('hidden');$('.modal').classList.toggle('detail-modal',detail);}
function closeModal(){$('#modal-backdrop').classList.add('hidden');$('#modal-content').innerHTML='';$('.modal').classList.remove('detail-modal');}
function openAuth(mode='login'){
  let heading='Welcome back',copy='Sign in to save itineraries, manage preferences and keep your travel plans in one place.';
  let fields='';
  if(mode==='register'){heading='Create your TourInsight account';copy='Save your plans and keep your travel preferences together.';fields=`<label class="field">Full name<input name="full_name" required minlength="2"></label><label class="field">Email<input name="email" type="email" required></label><label class="field">Origin city or state<input name="origin" placeholder="e.g. Bengaluru"></label><label class="field">Password<input name="password" type="password" required minlength="10" autocomplete="new-password"></label>`;}
  else if(mode==='forgot'){heading='Reset your password';copy='Enter the email address linked to your account. The local development reset link appears in the server terminal.';fields=`<label class="field">Email<input name="email" type="email" required></label>`;}
  else {fields=`<label class="field">Email<input name="email" type="email" required autocomplete="username"></label><label class="field">Password<input name="password" type="password" required autocomplete="current-password"></label>`;}
  showModal(`<span class="eyebrow">TOURINSIGHT ACCOUNT</span><h2 id="modal-title">${heading}</h2><p>${copy}</p><form class="auth-form" id="auth-form" data-mode="${mode}">${fields}<button class="button button-primary button-wide" type="submit">${mode==='register'?'Create account':mode==='forgot'?'Generate reset link':'Sign in'} →</button></form><div class="auth-switch">${mode==='login'?`New to TourInsight? <button data-auth-mode="register">Create account</button><br><button data-auth-mode="forgot">Forgot password?</button>`:mode==='register'?`Already have an account? <button data-auth-mode="login">Sign in</button>`:`Back to <button data-auth-mode="login">Sign in</button>`}</div>`);
}
function openResetModal(token){showModal(`<span class="eyebrow">ACCOUNT SECURITY</span><h2 id="modal-title">Choose a new password</h2><p>This one-time reset link expires after one hour.</p><form class="auth-form" id="reset-form"><input type="hidden" name="token" value="${esc(token)}"><label class="field">New password<input type="password" name="new_password" minlength="10" required autocomplete="new-password"></label><button class="button button-primary button-wide" type="submit">Update password →</button></form>`);}
function openProfile(){if(!state.user){openAuth('login');return;}showModal(`<span class="eyebrow">YOUR ACCOUNT</span><h2 id="modal-title">Profile settings</h2><p>Update your account details. Your login credentials remain private.</p><form id="profile-form" class="auth-form"><label class="field">Full name<input name="full_name" value="${esc(state.user.full_name)}" required></label><label class="field">Email<input value="${esc(state.user.email)}" disabled></label><label class="field">Origin city / state<input name="origin" value="${esc(state.user.origin||'')}"></label><button class="button button-primary" type="submit">Save profile</button></form><button class="button button-secondary button-wide" id="logout-button" style="margin-top:10px">Sign out</button>`);}

// Delegated actions and form handlers.
document.addEventListener('click',async e=>{
  const toolTab=e.target.closest('[data-tool-tab]');if(toolTab){switchTool(toolTab.dataset.toolTab);return;}
  const featureTabBtn=e.target.closest('[data-feature-tab]');if(featureTabBtn){featureTab(featureTabBtn.dataset.featureTab);if(featureTabBtn.dataset.featureTab==='districts')renderCommunityMap();return;}
  const districtBtn=e.target.closest('[data-district]');if(districtBtn){const d=districtBtn.dataset.district;const found=state.destinations.filter(x=>x.district===d);if(found.length&&state.communityMap){state.communityMap.fitBounds(found.map(x=>[x.latitude,x.longitude]),{padding:[35,35],maxZoom:9});}$('#district-search').value=d;renderDistricts(d);return;}
  const moveDay=e.target.closest('[data-move-day]');if(moveDay){const card=moveDay.closest('[data-plan-index]');movePlanStop(Number(card.dataset.planIndex),Number(moveDay.dataset.moveDay));return;}
  const openGroup=e.target.closest('[data-open-group]');if(openGroup){loadGroupBoard(openGroup.dataset.openGroup);openGroup.textContent='Refresh collaborative board ↻';return;}
  const voteSuggestion=e.target.closest('[data-vote-suggestion]');if(voteSuggestion){try{await api(`/groups/${voteSuggestion.dataset.groupId}/suggestions/${voteSuggestion.dataset.voteSuggestion}/vote`,{method:'POST',body:{}});loadGroupBoard(voteSuggestion.dataset.groupId);}catch(err){toast(err.message,'error');}return;}
  const copyCode=e.target.closest('[data-copy-code]');if(copyCode){const code=copyCode.dataset.copyCode;navigator.clipboard?.writeText(code).then(()=>toast('Invite code copied.')).catch(()=>toast('Invite code: '+code));return;}
  const delJournal=e.target.closest('[data-delete-journal]');if(delJournal){if(confirm('Delete this journal entry?')){try{await api('/journal/'+delJournal.dataset.deleteJournal,{method:'DELETE'});loadJournal();toast('Journal entry deleted.');}catch(err){toast(err.message,'error');}}return;}
  const packFilter=e.target.closest('[data-pack-filter]');if(packFilter){state.packingFilter=packFilter.dataset.packFilter;renderPacking();return;}
  const packTemplate=e.target.closest('[data-pack-template]');if(packTemplate){applyPackingTemplate(packTemplate.dataset.packTemplate);return;}
  const estimateLoad=e.target.closest('[data-estimate-load]');if(estimateLoad){loadEstimate(estimateLoad.dataset.estimateLoad);return;}
  const estimateDelete=e.target.closest('[data-estimate-delete]');if(estimateDelete){localStorage.setItem('tourinsight_budget_estimates',JSON.stringify(getEstimates().filter(x=>x.id!==Number(estimateDelete.dataset.estimateDelete))));renderSavedEstimates();toast('Estimate removed.');return;}
  const packDelete=e.target.closest('[data-pack-delete]');if(packDelete){state.packingItems=state.packingItems.filter(x=>x.id!==packDelete.dataset.packDelete);savePacking();renderPacking();return;}
  const pageBtn=e.target.closest('[data-page]');if(pageBtn){e.preventDefault();showPage(pageBtn.dataset.page);return;}
  const modeBtn=e.target.closest('[data-auth-mode]');if(modeBtn){openAuth(modeBtn.dataset.authMode);return;}
  const act=e.target.closest('[data-action]');if(act){const action=act.dataset.action;
    if(action==='destination-detail'){e.preventDefault();openDestinationDetail(act.dataset.slug);return;}
    if(action==='toggle-favorite'){e.preventDefault();e.stopPropagation();const slug=act.dataset.slug;if(state.savedPlaces.has(slug))state.savedPlaces.delete(slug);else state.savedPlaces.add(slug);localStorage.setItem('tourinsight_saved_places',JSON.stringify([...state.savedPlaces]));renderDestinationGrid();toast(state.savedPlaces.has(slug)?'Place saved to your collection.':'Place removed from saved places.');return;}
    if(action==='toggle-result'){const card=act.closest('.result-card');card.classList.toggle('expanded');act.textContent=card.classList.contains('expanded')?'Hide breakdown ↑':'View breakdown ↓';return;}
    if(action==='alternatives'){showAlternatives(act.dataset.slug);return;}
    if(action==='save-plan'){saveCurrentPlan();return;}
    if(action==='print-plan'){window.print();return;}
    if(action==='view-trip'){try{const d=await api('/itineraries/'+act.dataset.id);state.lastPlan=d.plan;renderPlan(d.plan);$('#planner-result').scrollIntoView({behavior:'smooth',block:'start'});}catch(err){toast(err.message,'error');}return;}
    if(action==='share-trip'){try{const d=await api('/itineraries/'+act.dataset.id+'/share',{method:'POST'});if(navigator.clipboard?.writeText){try{await navigator.clipboard.writeText(d.url);toast('Share link copied: '+d.url);}catch{prompt('Copy this share link',d.url);}}else prompt('Copy this share link',d.url);}catch(err){toast(err.message,'error');}return;}
    if(action==='delete-trip'){if(confirm('Delete this saved itinerary?')){try{await api('/itineraries/'+act.dataset.id,{method:'DELETE'});toast('Itinerary deleted.');loadSavedTrips();}catch(err){toast(err.message,'error');}}return;}
    if(action==='edit-destination'){const slug=act.dataset.slug;const current=state.destinations.find(x=>x.slug===slug);const cap=prompt(`Monthly visitor capacity for ${current?.name||slug} (leave blank to clear):`,current?.capacity_per_month??'');if(cap===null)return;const active=confirm('Keep this destination active in public discovery?');try{await api('/admin/destinations/'+slug,{method:'PATCH',body:{capacity_per_month:cap===''?null:Number(cap),active}});toast('Destination updated.');loadAdminDestinations();}catch(err){toast(err.message,'error');}return;}
  }
  if(e.target.id==='compare-selected'){compareSelected();return;}
  if(e.target.id==='saved-filter'){state.showSavedOnly=!state.showSavedOnly;renderDestinationGrid();return;}
  if(e.target.id==='auth-button'||e.target.id==='top-auth'){if(state.user)openProfile();else openAuth('login');return;}
  if(e.target.id==='profile-button'){openProfile();return;}
  if(e.target.id==='modal-close'||e.target.id==='modal-backdrop'){if(e.target.id==='modal-backdrop'||e.target.closest('#modal-close'))closeModal();return;}
  if(e.target.id==='mobile-menu'){$('#sidebar').classList.toggle('open');return;}
  if(e.target.id==='logout-button'){try{await api('/auth/logout',{method:'POST'});state.user=null;renderUser();closeModal();toast('Signed out.');if($('#view-community')?.classList.contains('active'))loadCommunity();}catch(err){toast(err.message,'error');}return;}
  if(e.target.classList.contains('admin-tab')){loadAdminTab(e.target.dataset.adminTab).catch(err=>toast(err.message,'error'));return;}
  if(e.target.id==='refresh-analytics'){loadAnalytics().catch(err=>toast(err.message,'error'));return;}
  if(e.target.id==='refresh-trips'){loadSavedTrips();return;}
  if(e.target.id==='refresh-admin-activity'){loadAdminActivity();return;}
  if(e.target.id==='sync-data-gov-in'){
    const button=e.target,result=$('#data-gov-result');button.disabled=true;button.textContent='Syncing resource…';result.textContent='Connecting to data.gov.in and validating returned records…';
    try{const d=await api('/admin/connectors/data-gov-in/sync',{method:'POST'});result.textContent=`Sync completed. Fetched ${d.records_fetched} record(s); mapped ${d.mapped_rows} row(s); inserted ${d.inserted}, updated ${d.updated||0}, skipped ${d.skipped}. ${d.note||''}`;toast('Government dataset sync completed.');await Promise.all([loadAnalytics(),loadPressure(),loadQuality()]);}
    catch(err){result.textContent=err.message;toast(err.message,'error');}
    finally{button.textContent='Sync selected resource';loadDataGovStatus();}
    return;
  }
  if(e.target.id==='refresh-admin-dest'){loadAdminDestinations();return;}
  if(e.target.id==='refresh-users'){loadAdminUsers();return;}
  if(e.target.id==='run-admin-quality'){runAdminQuality().catch(err=>toast(err.message,'error'));return;}
  if(e.target.id==='run-forecast'){loadForecast().then(()=>toast('Model availability check completed.')).catch(err=>toast(err.message,'error'));return;}
  if(e.target.id==='refresh-quality'){loadQuality().then(()=>toast('Data-quality summary refreshed.')).catch(err=>toast(err.message,'error'));return;}
});

document.addEventListener('change',async e=>{
  if(e.target.id==='district-search'){renderDistricts(e.target.value);return;}
  if(e.target.id==='transport-destination'){loadTransport(e.target.value);return;}
  if(e.target.id==='language-select'){applyLanguage(e.target.value);return;}
  if(e.target.matches('[data-pack-check]')){const item=state.packingItems.find(x=>x.id===e.target.dataset.packCheck);if(item){item.checked=e.target.checked;savePacking();renderPacking();}return;}
  if(e.target.id==='season-month'||e.target.id==='season-category'){loadSeasonalGuide().catch(err=>toast(err.message,'error'));return;}
  if(e.target.matches('[data-plan-stop]')){const stops=$$('[data-plan-stop]').map(x=>x.value);const payload={origin:state.lastPlan?.origin||'Bengaluru',month:state.lastPlan?.month||new Date().getMonth()+1,travellers:state.lastPlan?.travellers||1,destination_slugs:stops};try{const plan=await api('/itineraries/custom-preview',{method:'POST',body:payload});state.lastPlan=plan;renderPlan(plan);toast('Route updated with your selected stops.');}catch(err){toast(err.message,'error');}return;}
  if(e.target.matches('[data-compare]')){const slug=e.target.dataset.compare;if(e.target.checked){if(state.selectedCompare.size>=4){e.target.checked=false;toast('You can compare up to four destinations.','error');return;}state.selectedCompare.add(slug);}else state.selectedCompare.delete(slug);renderDestinationGrid();return;}
  if(e.target.matches('[data-weight-range]')){const key=e.target.dataset.weightRange;const n=$(`[data-weight-number="${key}"]`);if(n)n.value=e.target.value;updateWeightTotal();return;}
  if(e.target.matches('[data-weight-number]')){const key=e.target.dataset.weightNumber;const n=$(`[data-weight-range="${key}"]`);if(n)n.value=e.target.value;updateWeightTotal();return;}
  if(e.target.matches('[data-user-role]')){try{await api(`/admin/users/${e.target.dataset.userRole}/role?role=${e.target.value}`,{method:'PATCH'});toast('User role updated.');}catch(err){toast(err.message,'error');loadAdminUsers();}return;}
  if(e.target.matches('.file-drop input[type=file]')){const name=e.target.files[0]?.name||'No file selected';const target=e.target.closest('form').id==='tourism-upload-form'?'#tourism-file-name':'#reviews-file-name';$(target).textContent=name;return;}
  if(['dest-search','dest-region','dest-category','dest-sort'].includes(e.target.id)){renderDestinationGrid();return;}
  if(['analytics-destination','analytics-year'].includes(e.target.id)&&state.dashboard){renderAnalyticsCharts(state.dashboard).catch(err=>toast(err.message,'error'));return;}
});

$('#dest-search').addEventListener('input',()=>{clearTimeout(window.destSearchTimer);window.destSearchTimer=setTimeout(renderDestinationGrid,180);});
['budget-destination','budget-days','budget-people','cost-transport','cost-stay','cost-rooms','cost-food','cost-activities','cost-other','cost-buffer'].forEach(id=>$('#'+id)?.addEventListener('input',calcBudget));
$('#budget-destination')?.addEventListener('change',()=>{const d=state.destinations.find(x=>x.slug===$('#budget-destination').value);if(!d)return;const daily=(Number(d.budget_low||0)+Number(d.budget_high||0))/2;const days=Number($('#budget-days').value)||3,people=Number($('#budget-people').value)||2;$('#cost-stay').value=Math.round(daily*.4*2/100)*100;$('#cost-food').value=Math.round(daily*.25/50)*50;$('#cost-activities').value=Math.round(daily*.15*days/100)*100;$('#cost-transport').value=Math.round(daily*.15*days*people/100)*100;$('#cost-other').value=Math.round(daily*.05*days*people/100)*100;calcBudget();$('#budget-message').textContent='Cost fields were prefilled from the destination’s indicative daily budget. Adjust them to match actual quotes.';});
$('#budget-save')?.addEventListener('click',saveEstimate);$('#budget-export')?.addEventListener('click',exportBudget);$('#budget-reset')?.addEventListener('click',()=>{const defaults={'budget-days':3,'budget-people':2,'cost-transport':3000,'cost-stay':2200,'cost-rooms':1,'cost-food':700,'cost-activities':1200,'cost-other':500,'cost-buffer':10};Object.entries(defaults).forEach(([k,v])=>$('#'+k).value=v);calcBudget();});
$('#packing-add-form')?.addEventListener('submit',e=>{e.preventDefault();const input=$('#packing-custom'),label=input.value.trim();if(!label)return;state.packingItems.push({id:'custom-'+Date.now(),category:'My items',label,checked:false});input.value='';savePacking();renderPacking();toast('Item added to your checklist.');});
$('#packing-export')?.addEventListener('click',exportPacking);$('#packing-reset')?.addEventListener('click',()=>{if(confirm('Clear all packed checkmarks?')){state.packingItems.forEach(x=>x.checked=false);savePacking();renderPacking();}});

$('#recommend-form').addEventListener('submit',e=>{e.preventDefault();submitRecommendations(e.target);});
$('#planner-form').addEventListener('submit',e=>{e.preventDefault();submitPlanner(e.target);});
$('#review-form').addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(e.target);let image_url='';try{const photo=$('#review-photo')?.files[0];if(photo){const up=new FormData();up.append('file',photo);image_url=(await api('/community/upload',{method:'POST',body:up})).url;}const body={destination_slug:fd.get('destination_slug'),author:fd.get('author')||'Tourist',rating:Number(fd.get('rating')),review_text:fd.get('review_text'),image_url};const d=await api('/reviews',{method:'POST',body});toast(d.message+` Sentiment tagged ${d.sentiment}.`);e.target.reset();await loadSentiment();}catch(err){toast(err.message,'error');}});
$('#auth-form')?.addEventListener('submit',()=>{});
document.addEventListener('submit',async e=>{
  if(e.target.id==='community-post-form'){e.preventDefault();if(!state.user){openAuth('login');toast('Sign in to publish a community post.','error');return;}const form=e.target,fd=new FormData(form);let imageUrl='';const photo=$('#community-photo').files[0];try{if(photo){const up=new FormData();up.append('file',photo);const uploaded=await api('/community/upload',{method:'POST',body:up});imageUrl=uploaded.url;}const body={title:fd.get('title'),destination_slug:fd.get('destination_slug'),post_type:fd.get('post_type'),body:fd.get('body'),image_url:imageUrl};await api('/community/posts',{method:'POST',body});form.reset();await loadCommunityFeed();toast('Your post is live in the local community.');}catch(err){toast(err.message,'error');}return;}
  if(e.target.matches('[data-group-suggest-form]')){e.preventDefault();const fd=new FormData(e.target),gid=e.target.dataset.groupSuggestForm;try{const d=await api(`/groups/${gid}/suggestions`,{method:'POST',body:{destination_slug:fd.get('destination_slug'),note:fd.get('note')}});toast(d.message);loadGroupBoard(gid);}catch(err){toast(err.message,'error');}return;}
  if(e.target.id==='group-create-form'){e.preventDefault();if(!state.user){openAuth('login');toast('Sign in to create a trip group.','error');return;}const fd=new FormData(e.target);try{const body={name:fd.get('name'),itinerary_id:fd.get('itinerary_id')?Number(fd.get('itinerary_id')):null};const d=await api('/groups',{method:'POST',body});toast(d.message+' Code: '+d.invite_code);e.target.reset();loadGroups();}catch(err){toast(err.message,'error');}return;}
  if(e.target.id==='group-join-form'){e.preventDefault();if(!state.user){openAuth('login');return;}const fd=new FormData(e.target);try{const d=await api('/groups/join',{method:'POST',body:{invite_code:fd.get('invite_code')}});toast(d.message);e.target.reset();loadGroups();}catch(err){toast(err.message,'error');}return;}
  if(e.target.id==='journal-form'){e.preventDefault();if(!state.user){openAuth('login');toast('Sign in to save your travel journal.','error');return;}const fd=new FormData(e.target);try{const body=Object.fromEntries(fd.entries());await api('/journal',{method:'POST',body});e.target.reset();loadJournal();toast('Journal entry saved.');}catch(err){toast(err.message,'error');}return;}
  if(e.target.id==='checkin-form'){e.preventDefault();if(!state.user){openAuth('login');toast('Sign in to record visits.','error');return;}const fd=new FormData(e.target);try{const d=await api('/checkins',{method:'POST',body:Object.fromEntries(fd.entries())});toast(d.message);loadPassport();}catch(err){toast(err.message,'error');}return;}
  if(e.target.id==='auth-form'){e.preventDefault();const mode=e.target.dataset.mode;const fd=new FormData(e.target);try{if(mode==='login'){const d=await api('/auth/login',{method:'POST',body:{email:fd.get('email'),password:fd.get('password')}});state.user=d.user;renderUser();closeModal();toast('Welcome back, '+state.user.full_name.split(' ')[0]+'.');if($('#view-community')?.classList.contains('active'))loadCommunity();}else if(mode==='register'){const d=await api('/auth/register',{method:'POST',body:{email:fd.get('email'),full_name:fd.get('full_name'),origin:fd.get('origin'),password:fd.get('password')}});state.user=d.user;renderUser();closeModal();toast('Your account is ready.');if($('#view-community')?.classList.contains('active'))loadCommunity();}else{const d=await api('/auth/forgot-password',{method:'POST',body:{email:fd.get('email')}});toast(d.message);closeModal();}}catch(err){toast(err.message,'error');}return;}
  if(e.target.id==='reset-form'){e.preventDefault();const fd=new FormData(e.target);try{const d=await api('/auth/reset-password',{method:'POST',body:{token:fd.get('token'),new_password:fd.get('new_password')}});state.user=d.user;renderUser();closeModal();history.replaceState({},'',location.pathname+'#overview');toast('Password updated.');}catch(err){toast(err.message,'error');}return;}
  if(e.target.id==='profile-form'){e.preventDefault();const fd=new FormData(e.target);try{const d=await api('/auth/profile',{method:'POST',body:{full_name:fd.get('full_name'),origin:fd.get('origin')}});state.user=d.user;renderUser();closeModal();toast('Profile updated.');}catch(err){toast(err.message,'error');}return;}
  if(e.target.id==='tourism-upload-form'){e.preventDefault();await uploadCsv(e.target,'/admin/import/tourism-stats','#tourism-import-result');return;}
  if(e.target.id==='reviews-upload-form'){e.preventDefault();await uploadCsv(e.target,'/admin/import/reviews','#reviews-import-result');return;}
  if(e.target.id==='weight-form'){e.preventDefault();const weights={};$$('[data-weight-number]',e.target).forEach(x=>weights[x.dataset.weightNumber]=Number(x.value));try{const d=await api('/admin/weights',{method:'PUT',body:{weights}});toast(d.message);loadWeightEditor();}catch(err){toast(err.message,'error');}return;}
  if(e.target.id==='add-destination-form'){e.preventDefault();const fd=new FormData(e.target);const body=Object.fromEntries(fd.entries());for(const k of ['latitude','longitude','budget_low','budget_high','accessibility_score','popularity_index','capacity_per_month'])body[k]=body[k]===''?null:Number(body[k]);try{const d=await api('/admin/destinations',{method:'POST',body});toast(d.message);e.target.reset();await refreshDestinations();loadAdminDestinations();}catch(err){toast(err.message,'error');}return;}
  if(e.target.id==='add-source-form'){e.preventDefault();const body=Object.fromEntries(new FormData(e.target).entries());try{const d=await api('/admin/sources',{method:'POST',body});toast(d.message);e.target.reset();loadAdminSources();}catch(err){toast(err.message,'error');}return;}
});
async function uploadCsv(form,path,resultId){const out=$(resultId);out.textContent='Uploading and validating the CSV…';const fd=new FormData(form);try{const d=await api(path,{method:'POST',body:fd});out.textContent=`Imported ${d.inserted} row(s); updated ${d.updated||0}; skipped ${d.skipped}. ${d.capacity_updates?`Updated ${d.capacity_updates} capacity value(s).`:''} ${d.errors?.length?`First issue: ${d.errors[0].reason}`:''}`;toast('CSV import completed.');form.reset();if(path.includes('tourism'))loadAnalytics();else loadSentiment();}catch(err){out.textContent=err.message;toast(err.message,'error');}}
async function compareSelected(){const slugs=[...state.selectedCompare];if(slugs.length<2)return;try{const d=await api('/destinations/compare',{method:'POST',body:{slugs,month:Number($('#rec-month').value)}});$('#compare-output').classList.remove('hidden');$('#compare-output').innerHTML=`<div class="compare-table-wrap"><table><thead><tr><th>Measure</th>${d.destinations.map(x=>`<th>${esc(x.name)}</th>`).join('')}</tr></thead><tbody><tr><td>Category</td>${d.destinations.map(x=>`<td>${esc(x.category)}</td>`).join('')}</tr><tr><td>Season suitability · ${MONTHS[Number($('#rec-month').value)-1]}</td>${d.destinations.map(x=>`<td>${x.seasonal_score??'—'}/100</td>`).join('')}</tr><tr><td>Indicative budget/day</td>${d.destinations.map(x=>`<td>${money(x.budget_low)}–${money(x.budget_high)}</td>`).join('')}</tr><tr><td>Accessibility baseline</td>${d.destinations.map(x=>`<td>${x.accessibility_score??'—'}/100</td>`).join('')}</tr><tr><td>Visitor rating</td>${d.destinations.map(x=>`<td>${x.rating?`★ ${x.rating.average} (${x.rating.count})`:'Not available'}</td>`).join('')}</tr><tr><td>Recommended duration</td>${d.destinations.map(x=>`<td>${x.visit_days} day(s)</td>`).join('')}</tr></tbody></table></div>`;$('#compare-output').scrollIntoView({behavior:'smooth',block:'nearest'});}catch(e){toast(e.message,'error');}}


let draggedPlanIndex=null;
