$('#language-select')?.addEventListener('change',e=>applyLanguage(e.target.value));

// Close menus / reset hash on navigation and load first screen.
window.addEventListener('hashchange',()=>{const page=location.hash.slice(1);if(page&&$('#view-'+page)&&!$('.view.active')?.id.endsWith(page))showPage(page);});
init().catch(e=>{console.error(e);toast('TourInsight could not initialize: '+e.message,'error');});


/* TourInsight 3.1 motion system: reversible scroll reveals, scroll progress and navigation rhythm. */
(()=>{
  if(window.__tourInsightMotionBooted)return;window.__tourInsightMotionBooted=true;
  const reduce=window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  const progress=document.querySelector('#scroll-progress span');
  const topButton=document.querySelector('#back-to-top');
  const header=document.querySelector('#sidebar');
  let lastY=window.scrollY||0,scrollTick=false,scrollDirection='down';
  const updateScroll=()=>{
    const y=window.scrollY||0,max=Math.max(1,document.documentElement.scrollHeight-window.innerHeight);
    if(progress)progress.style.transform=`scaleX(${Math.min(1,Math.max(0,y/max))})`;
    if(topButton)topButton.classList.toggle('is-visible',y>480);
    const delta=y-lastY;
    if(Math.abs(delta)>5){scrollDirection=delta>0?'down':'up';document.body.dataset.scrollDir=scrollDirection;
      if(header&&y>160){header.classList.toggle('is-scroll-hidden',scrollDirection==='down');}else if(header){header.classList.remove('is-scroll-hidden');}
      lastY=y;
    }
    scrollTick=false;
  };
  window.addEventListener('scroll',()=>{if(!scrollTick){requestAnimationFrame(updateScroll);scrollTick=true;}},{passive:true});
  window.addEventListener('resize',updateScroll,{passive:true});updateScroll();
  topButton?.addEventListener('click',()=>window.scrollTo({top:0,behavior:reduce?'auto':'smooth'}));

  const revealSelector='.welcome-row,.hero-panel,.section-heading,.kpi-card,.panel,.feature-card,.page-title-row,.filter-bar,.source-note,.destination-card,.result-card,.opportunity-card,.feature-section-head,.feature-pane,.neo-feature-hero,.service-category-label,.service-tile,.service-hub-foot,.district-card,.community-post,.journal-entry,.passport-card,.transport-option,.app-footer';
  const revealNodes=new WeakSet();
  let observer=null;
  if('IntersectionObserver' in window&&!reduce){
    observer=new IntersectionObserver(entries=>entries.forEach(entry=>{
      const el=entry.target;
      if(entry.isIntersecting){el.classList.add('ti-in');el.style.setProperty('--ti-delay',`${Math.min(Number(el.dataset.tiIndex||0)%4,3)*55}ms`);}
      else{el.classList.remove('ti-in');}
    }),{threshold:.12,rootMargin:'0px 0px -7% 0px'});
  }
  function scanReveal(root=document){
    if(reduce){return;}
    const nodes=[];
    if(root.matches?.(revealSelector))nodes.push(root);
    root.querySelectorAll?.(revealSelector).forEach(n=>nodes.push(n));
    nodes.forEach((el,index)=>{
      if(revealNodes.has(el))return;revealNodes.add(el);el.classList.add('ti-reveal');el.dataset.tiIndex=String(index);
      if(observer)observer.observe(el);else el.classList.add('ti-in');
    });
  }
  scanReveal();
  const mutation=new MutationObserver(records=>records.forEach(r=>r.addedNodes.forEach(n=>{if(n.nodeType===1)scanReveal(n);} )));
  mutation.observe(document.querySelector('.page-content')||document.body,{childList:true,subtree:true});
  // Re-arm reveals whenever a different app view is selected, including client-rendered sections.
  document.addEventListener('click',e=>{if(e.target.closest('[data-page]'))requestAnimationFrame(()=>scanReveal(document.querySelector('.view.active')||document));});
  window.addEventListener('hashchange',()=>requestAnimationFrame(()=>scanReveal(document.querySelector('.view.active')||document)));
})();

/* TourInsight 3.2 — restrained pointer light and low-amplitude hero parallax. */
(()=>{
  if(window.__tourInsightExperience32)return;window.__tourInsightExperience32=true;
  const reduce=window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;
  if(reduce)return;
  document.querySelectorAll('.service-tile').forEach(card=>{
    card.addEventListener('pointermove',event=>{
      const rect=card.getBoundingClientRect();
      card.style.setProperty('--ti-pointer-x',`${event.clientX-rect.left}px`);
      card.style.setProperty('--ti-pointer-y',`${event.clientY-rect.top}px`);
    },{passive:true});
    card.addEventListener('pointerleave',()=>{
      card.style.removeProperty('--ti-pointer-x');card.style.removeProperty('--ti-pointer-y');
    },{passive:true});
  });
  const hero=document.querySelector('.hero-image');let pending=false;
  const parallax=()=>{
    if(!hero){pending=false;return;}
    const rect=hero.getBoundingClientRect();
    if(rect.bottom>0&&rect.top<window.innerHeight){
      const progress=(window.innerHeight-rect.top)/(window.innerHeight+rect.height);
      hero.style.setProperty('--ti-hero-parallax',`${Math.round((progress-.5)*24)}px`);
    }
    pending=false;
  };
  window.addEventListener('scroll',()=>{if(!pending){pending=true;requestAnimationFrame(parallax);}},{passive:true});
  window.addEventListener('resize',parallax,{passive:true});parallax();
})();
